import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail } from 'lucide-react';
import { AppConfig } from '../types';

interface CloudAuthModalProps {
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onResetPassword: (email: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  onLogin, onResetPassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  const clearMsg = () => setMsg(null);

  const handleSubmit = async () => {
    clearMsg();
    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // Reset Password Flow
    if (mode === 'reset') {
        setLoading(true);
        try {
            const err = await onResetPassword(email);
            if (err) setMsg({ type: 'err', text: err });
            else setMsg({ type: 'success', text: '重置邮件已发送，请检查邮箱 (含垃圾箱)' });
        } catch(e: any) {
            setMsg({ type: 'err', text: e.message });
        }
        setLoading(false);
        return;
    }

    // Login/Signup Flow
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: 'login' | 'signup' | 'reset') => {
      setMode(m);
      clearMsg();
      // Keep email, clear passwords
      setPassword('');
      setConfirmPass('');
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Cloud className="text-blue-600"/> 
            {currentUser ? '账号中心' : (mode === 'login' ? '登录' : (mode === 'signup' ? '注册账号' : '找回密码'))}
          </h3>
          <button onClick={onClose}><X className="text-gray-400"/></button>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {currentUser ? (
            <div className="text-center py-6">
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <Cloud size={32}/>
              </div>
              <p className="font-bold text-lg text-gray-800">已登录</p>
              <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
              <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
              <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                退出登录
              </button>
            </div>
        ) : (
          <div className="space-y-4">

            <div>
              <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
              <div className="relative">
                  <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                  <input 
                    type="email" 
                    value={email} 
                    onChange={e => setEmail(e.target.value)} 
                    className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                    placeholder="email@example.com"
                  />
              </div>
            </div>

            {mode !== 'reset' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="******"
                      />
                  </div>
                </div>
            )}

            {mode === 'signup' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">确认密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={confirmPass} 
                        onChange={e => setConfirmPass(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="再次输入密码"
                      />
                  </div>
                </div>
            )}

            <div className="pt-2">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading}
                    className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                >
                    {loading ? '处理中...' : (
                        mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                        (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : <><Send size={16}/> 发送重置链接</>)
                    )}
                </button>
            </div>

            <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                {mode === 'login' && (
                    <>
                        <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                        <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                    </>
                )}
                {mode === 'signup' && (
                    <div className="w-full text-center">
                        <span className="text-gray-400 font-normal">已有账号? </span>
                        <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                    </div>
                )}
                {mode === 'reset' && (
                     <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                        <ArrowLeft size={12}/> 返回登录
                     </button>
                )}
            </div>

            <div className="mt-6 pt-4 border-t border-gray-100">
                <h4 className="text-xs font-bold text-gray-400 mb-2 flex items-center gap-1"><HelpCircle size={12}/> 提示</h4>
                <p className="text-[10px] text-gray-500 leading-relaxed">
                  {mode === 'reset' 
                    ? '系统将发送包含重置链接的邮件到您的邮箱，请点击链接后重新设置密码。' 
                    : '登录后数据将自动同步。新设备登录相同账号即可同步数据。'}
                </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client using HARDCODED constants (SaaS Mode)
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();

    // Check if configured properly
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        // Check session
        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        const { data: { subscription } } = client.auth.onAuthStateChange((_event, session) => {
          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => subscription.unsubscribe();
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // 2. Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       // Cloud has data, overwrite local
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    } else if (!data && !error) {
       // No cloud data, upload local
       syncToCloud(client, userId, history.present);
    }
  };

  // 3. Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    if (isSignup) {
      const { data, error } = await cloudClient.auth.signUp({ email, password: pass });
      if (error) return error.message;
      // If email confirmation is enabled (default) and not clicked yet, session is null.
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  const handlePasswordReset = async (email: string) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';
    const { error } = await cloudClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.href
    });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates with Cloud Sync ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));

    // Sync to cloud if logged in
    if (cloudClient && cloudUser) {
        syncToCloud(cloudClient, cloudUser.id, newRooms);
    }
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          onLogin={handleCloudLogin}
          onResetPassword={handlePasswordReset}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail, KeyRound } from 'lucide-react';
import { AppConfig } from '../types';

interface CloudAuthModalProps {
  initialMode?: 'login' | 'signup' | 'reset' | 'update';
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onResetPassword: (email: string) => Promise<string | void>;
  onUpdatePassword: (pass: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  initialMode = 'login', onLogin, onResetPassword, onUpdatePassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset' | 'update'>(initialMode);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  const clearMsg = () => setMsg(null);

  const handleSubmit = async () => {
    clearMsg();

    // Update Password Flow (Recovery)
    if (mode === 'update') {
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onUpdatePassword(password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功，请重新登录' });
                setTimeout(() => {
                    onClose();
                    setMode('login'); // Reset for next time
                }, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // Reset Password Flow (Request Link)
    if (mode === 'reset') {
        setLoading(true);
        try {
            const err = await onResetPassword(email);
            if (err) setMsg({ type: 'err', text: err });
            else setMsg({ type: 'success', text: '重置邮件已发送，请检查邮箱 (含垃圾箱)' });
        } catch(e: any) {
            setMsg({ type: 'err', text: e.message });
        }
        setLoading(false);
        return;
    }

    // Login/Signup Flow
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
        if (!isSignup) onClose();
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: 'login' | 'signup' | 'reset') => {
      setMode(m);
      clearMsg();
      setPassword('');
      setConfirmPass('');
  };

  const getTitle = () => {
      if (mode === 'update') return '重置密码';
      if (currentUser) return '账号中心';
      if (mode === 'signup') return '注册账号';
      if (mode === 'reset') return '找回密码';
      return '登录';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Cloud className="text-blue-600"/> 
            {getTitle()}
          </h3>
          <button onClick={onClose}><X className="text-gray-400"/></button>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {/* Show profile ONLY if logged in AND NOT in update mode (recovery) */}
        {currentUser && mode !== 'update' ? (
            <div className="text-center py-6">
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <Cloud size={32}/>
              </div>
              <p className="font-bold text-lg text-gray-800">已登录</p>
              <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
              <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
              <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                退出登录
              </button>
            </div>
        ) : (
          <div className="space-y-4">

            {mode !== 'update' && (
                <div>
                <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
                <div className="relative">
                    <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                    <input 
                        type="email" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="email@example.com"
                    />
                </div>
                </div>
            )}

            {mode !== 'reset' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">{mode === 'update' ? '新密码' : '密码'}</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="******"
                      />
                  </div>
                </div>
            )}

            {(mode === 'signup' || mode === 'update') && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">确认密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={confirmPass} 
                        onChange={e => setConfirmPass(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="再次输入密码"
                      />
                  </div>
                </div>
            )}

            <div className="pt-2">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading}
                    className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                >
                    {loading ? '处理中...' : (
                        mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                        (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : 
                        (mode === 'reset' ? <><Send size={16}/> 发送重置链接</> : <><KeyRound size={16}/> 修改密码</>))
                    )}
                </button>
            </div>

            <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                {mode === 'login' && (
                    <>
                        <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                        <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                    </>
                )}
                {mode === 'signup' && (
                    <div className="w-full text-center">
                        <span className="text-gray-400 font-normal">已有账号? </span>
                        <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                    </div>
                )}
                {mode === 'reset' && (
                     <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                        <ArrowLeft size={12}/> 返回登录
                     </button>
                )}
            </div>

            {mode !== 'update' && (
                <div className="mt-6 pt-4 border-t border-gray-100">
                    <h4 className="text-xs font-bold text-gray-400 mb-2 flex items-center gap-1"><HelpCircle size={12}/> 提示</h4>
                    <p className="text-[10px] text-gray-500 leading-relaxed">
                    {mode === 'reset' 
                        ? '系统将发送重置链接到邮箱。若收到空白邮件，可能是Supabase后台模板配置问题，请联系管理员。' 
                        : '登录后数据将自动同步。新设备登录相同账号即可同步数据。'}
                    </p>
                </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client using HARDCODED constants (SaaS Mode)
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();

    // Check if configured properly
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        // Check session
        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        const { data: { subscription } } = client.auth.onAuthStateChange((event, session) => {
          // Handle Password Recovery Event
          if (event === 'PASSWORD_RECOVERY') {
            setModal({ type: 'cloudAuth', data: { mode: 'update' } });
          }

          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => subscription.unsubscribe();
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // 2. Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       // Cloud has data, overwrite local
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    } else if (!data && !error) {
       // No cloud data, upload local
       syncToCloud(client, userId, history.present);
    }
  };

  // 3. Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    if (isSignup) {
      // Provide emailRedirectTo to ensure the link is generated correctly for the current environment
      const { data, error } = await cloudClient.auth.signUp({ 
          email, 
          password: pass,
          options: { emailRedirectTo: window.location.origin } 
      });

      if (error) return error.message;
      // If email confirmation is enabled (default) and not clicked yet, session is null.
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  const handlePasswordReset = async (email: string) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';
    const { error } = await cloudClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin
    });
    return error?.message;
  };

  const handleUpdatePassword = async (pass: string) => {
    if (!cloudClient) return '系统未配置数据库';
    const { error } = await cloudClient.auth.updateUser({ password: pass });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates with Cloud Sync ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));

    // Sync to cloud if logged in
    if (cloudClient && cloudUser) {
        syncToCloud(cloudClient, cloudUser.id, newRooms);
    }
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          initialMode={modal.data?.mode}
          onLogin={handleCloudLogin}
          onResetPassword={handlePasswordReset}
          onUpdatePassword={handleUpdatePassword}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail, KeyRound, Settings, Copy } from 'lucide-react';

interface CloudAuthModalProps {
  initialMode?: 'login' | 'signup' | 'reset' | 'update';
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onResetPassword: (email: string) => Promise<string | void>;
  onUpdatePassword: (pass: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

const TEMPLATES = {
  confirm: {
    subject: "验证您的房租管家账号",
    body: `<h2>欢迎注册房租管家</h2>
<p>请点击下方链接完成邮箱验证：</p>
<p><a href="{{ .ConfirmationURL }}" style="display:inline-block;background:#2563EB;color:white;padding:10px 20px;border-radius:5px;text-decoration:none;font-weight:bold;">验证我的邮箱</a></p>
<p style="font-size:12px;color:#666;">如果链接无法点击，请复制以下网址到浏览器打开：<br>{{ .ConfirmationURL }}</p>`
  },
  reset: {
    subject: "重置您的房租管家密码",
    body: `<h2>重置密码请求</h2>
<p>您已申请重置密码。请点击下方链接设置新密码：</p>
<p><a href="{{ .ConfirmationURL }}" style="display:inline-block;background:#2563EB;color:white;padding:10px 20px;border-radius:5px;text-decoration:none;font-weight:bold;">前往重置密码</a></p>
<p style="font-size:12px;color:#666;">如果链接无法点击，请复制以下网址到浏览器打开：<br>{{ .ConfirmationURL }}</p>`
  }
};

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  initialMode = 'login', onLogin, onResetPassword, onUpdatePassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset' | 'update' | 'config'>(initialMode);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  const clearMsg = () => setMsg(null);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text).then(() => {
        setMsg({ type: 'success', text: '配置内容已复制' });
    });
  };

  const handleSubmit = async () => {
    clearMsg();

    // Update Password Flow
    if (mode === 'update') {
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onUpdatePassword(password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功，请重新登录' });
                setTimeout(() => {
                    onClose();
                    setMode('login'); 
                }, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // Reset Password Request Flow
    if (mode === 'reset') {
        setLoading(true);
        try {
            const err = await onResetPassword(email);
            if (err) setMsg({ type: 'err', text: err });
            else setMsg({ type: 'success', text: '重置邮件已发送。如未收到或空白，请点击右上角设置图标查看配置。' });
        } catch(e: any) {
            setMsg({ type: 'err', text: e.message });
        }
        setLoading(false);
        return;
    }

    // Login/Signup Flow
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。如邮件空白，请查看配置指南。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
        if (!isSignup) onClose();
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: any) => {
      setMode(m);
      clearMsg();
      setPassword('');
      setConfirmPass('');
  };

  const getTitle = () => {
      if (mode === 'config') return '邮件模板配置指南';
      if (mode === 'update') return '重置密码';
      if (currentUser) return '账号中心';
      if (mode === 'signup') return '注册账号';
      if (mode === 'reset') return '找回密码';
      return '登录';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            {mode === 'config' ? <Settings className="text-gray-600"/> : <Cloud className="text-blue-600"/>}
            {getTitle()}
          </h3>
          <div className="flex items-center gap-3">
             {mode !== 'config' && !currentUser && (
                 <button onClick={() => switchMode('config')} className="text-gray-300 hover:text-gray-600" title="邮件配置">
                     <Settings size={18} />
                 </button>
             )}
             <button onClick={onClose}><X className="text-gray-400"/></button>
          </div>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {mode === 'config' ? (
             <div className="space-y-6">
                 <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-100">
                     <p className="text-xs text-yellow-800 font-bold leading-relaxed">
                         如果您收到的邮件是空白的，请登录 Supabase 后台 (Authentication -&gt; Email Templates)，将以下内容填入对应位置。
                     </p>
                 </div>

                 <div>
                     <div className="flex justify-between items-center mb-1">
                        <h4 className="font-bold text-sm text-gray-800">1. Confirm Signup (注册验证)</h4>
                        <button onClick={() => copyToClipboard(TEMPLATES.confirm.body)} className="text-blue-600 text-xs font-bold flex items-center gap-1"><Copy size={12}/> 复制HTML</button>
                     </div>
                     <div className="text-xs text-gray-500 mb-1">Subject: <span className="font-mono text-black">{TEMPLATES.confirm.subject}</span></div>
                     <div className="bg-gray-50 p-2 rounded border text-[10px] font-mono text-gray-600 h-24 overflow-y-auto">
                         {TEMPLATES.confirm.body}
                     </div>
                 </div>

                 <div>
                     <div className="flex justify-between items-center mb-1">
                        <h4 className="font-bold text-sm text-gray-800">2. Reset Password (重置密码)</h4>
                        <button onClick={() => copyToClipboard(TEMPLATES.reset.body)} className="text-blue-600 text-xs font-bold flex items-center gap-1"><Copy size={12}/> 复制HTML</button>
                     </div>
                     <div className="text-xs text-gray-500 mb-1">Subject: <span className="font-mono text-black">{TEMPLATES.reset.subject}</span></div>
                     <div className="bg-gray-50 p-2 rounded border text-[10px] font-mono text-gray-600 h-24 overflow-y-auto">
                         {TEMPLATES.reset.body}
                     </div>
                 </div>

                 <button onClick={() => switchMode('login')} className="w-full py-3 bg-gray-100 text-gray-600 rounded-lg font-bold">
                     返回登录
                 </button>
             </div>
        ) : (
          <>
            {/* Standard Auth Views */}
            {currentUser && mode !== 'update' ? (
                <div className="text-center py-6">
                <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Cloud size={32}/>
                </div>
                <p className="font-bold text-lg text-gray-800">已登录</p>
                <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
                <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
                <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                    退出登录
                </button>
                </div>
            ) : (
            <div className="space-y-4">

                {mode !== 'update' && (
                    <div>
                    <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
                    <div className="relative">
                        <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                        <input 
                            type="email" 
                            value={email} 
                            onChange={e => setEmail(e.target.value)} 
                            className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                            placeholder="email@example.com"
                        />
                    </div>
                    </div>
                )}

                {mode !== 'reset' && (
                    <div>
                    <label className="text-xs font-bold text-gray-400 mb-1 block">{mode === 'update' ? '新密码' : '密码'}</label>
                    <div className="relative">
                        <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                        <input 
                            type="password" 
                            value={password} 
                            onChange={e => setPassword(e.target.value)} 
                            className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                            placeholder="******"
                        />
                    </div>
                    </div>
                )}

                {(mode === 'signup' || mode === 'update') && (
                    <div>
                    <label className="text-xs font-bold text-gray-400 mb-1 block">确认密码</label>
                    <div className="relative">
                        <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                        <input 
                            type="password" 
                            value={confirmPass} 
                            onChange={e => setConfirmPass(e.target.value)} 
                            className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                            placeholder="再次输入密码"
                        />
                    </div>
                    </div>
                )}

                <div className="pt-2">
                    <button 
                        onClick={handleSubmit} 
                        disabled={loading}
                        className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                    >
                        {loading ? '处理中...' : (
                            mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                            (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : 
                            (mode === 'reset' ? <><Send size={16}/> 发送重置链接</> : <><KeyRound size={16}/> 修改密码</>))
                        )}
                    </button>
                </div>

                <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                    {mode === 'login' && (
                        <>
                            <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                            <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                        </>
                    )}
                    {mode === 'signup' && (
                        <div className="w-full text-center">
                            <span className="text-gray-400 font-normal">已有账号? </span>
                            <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                        </div>
                    )}
                    {mode === 'reset' && (
                        <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                            <ArrowLeft size={12}/> 返回登录
                        </button>
                    )}
                </div>

                {mode !== 'update' && (
                    <div className="mt-6 pt-4 border-t border-gray-100">
                        <h4 className="text-xs font-bold text-gray-400 mb-2 flex items-center gap-1"><HelpCircle size={12}/> 提示</h4>
                        <p className="text-[10px] text-gray-500 leading-relaxed">
                        {mode === 'reset' 
                            ? '系统将发送重置链接到邮箱。' 
                            : '登录后数据将自动同步。新设备登录相同账号即可同步数据。'}
                        </p>
                    </div>
                )}
            </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client using HARDCODED constants (SaaS Mode)
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();

    // Check if configured properly
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        // Check session
        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        const { data: { subscription } } = client.auth.onAuthStateChange((event, session) => {
          // Handle Password Recovery Event
          if (event === 'PASSWORD_RECOVERY') {
            setModal({ type: 'cloudAuth', data: { mode: 'update' } });
          }

          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => subscription.unsubscribe();
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // 2. Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       // Cloud has data, overwrite local
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    } else if (!data && !error) {
       // No cloud data, upload local
       syncToCloud(client, userId, history.present);
    }
  };

  // 3. Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    if (isSignup) {
      // Use window.location.href to be safe
      const { data, error } = await cloudClient.auth.signUp({ 
          email, 
          password: pass,
          options: { emailRedirectTo: window.location.href } 
      });

      if (error) return error.message;
      // If email confirmation is enabled (default) and not clicked yet, session is null.
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  const handlePasswordReset = async (email: string) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';
    const { error } = await cloudClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.href
    });
    return error?.message;
  };

  const handleUpdatePassword = async (pass: string) => {
    if (!cloudClient) return '系统未配置数据库';
    const { error } = await cloudClient.auth.updateUser({ password: pass });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates with Cloud Sync ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));

    // Sync to cloud if logged in
    if (cloudClient && cloudUser) {
        syncToCloud(cloudClient, cloudUser.id, newRooms);
    }
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          initialMode={modal.data?.mode}
          onLogin={handleCloudLogin}
          onResetPassword={handlePasswordReset}
          onUpdatePassword={handleUpdatePassword}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail, KeyRound } from 'lucide-react';

interface CloudAuthModalProps {
  initialMode?: 'login' | 'signup' | 'reset' | 'update';
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onResetPassword: (email: string) => Promise<string | void>;
  onUpdatePassword: (pass: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  initialMode = 'login', onLogin, onResetPassword, onUpdatePassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset' | 'update'>(initialMode);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  const clearMsg = () => setMsg(null);

  const handleSubmit = async () => {
    clearMsg();

    // Update Password Flow
    if (mode === 'update') {
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onUpdatePassword(password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功，请重新登录' });
                setTimeout(() => {
                    onClose();
                    setMode('login'); 
                }, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // Reset Password Request Flow
    if (mode === 'reset') {
        setLoading(true);
        try {
            const err = await onResetPassword(email);
            if (err) setMsg({ type: 'err', text: err });
            else setMsg({ type: 'success', text: '重置邮件已发送，请检查邮箱 (含垃圾箱)' });
        } catch(e: any) {
            setMsg({ type: 'err', text: e.message });
        }
        setLoading(false);
        return;
    }

    // Login/Signup Flow
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
        if (!isSignup) onClose();
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: any) => {
      setMode(m);
      clearMsg();
      setPassword('');
      setConfirmPass('');
  };

  const getTitle = () => {
      if (mode === 'update') return '重置密码';
      if (currentUser) return '账号中心';
      if (mode === 'signup') return '注册账号';
      if (mode === 'reset') return '找回密码';
      return '登录';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Cloud className="text-blue-600"/> 
            {getTitle()}
          </h3>
          <button onClick={onClose}><X className="text-gray-400"/></button>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {currentUser && mode !== 'update' ? (
            <div className="text-center py-6">
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <Cloud size={32}/>
              </div>
              <p className="font-bold text-lg text-gray-800">已登录</p>
              <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
              <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
              <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                退出登录
              </button>
            </div>
        ) : (
          <div className="space-y-4">

            {mode !== 'update' && (
                <div>
                <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
                <div className="relative">
                    <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                    <input 
                        type="email" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="email@example.com"
                    />
                </div>
                </div>
            )}

            {mode !== 'reset' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">{mode === 'update' ? '新密码' : '密码'}</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="******"
                      />
                  </div>
                </div>
            )}

            {(mode === 'signup' || mode === 'update') && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">确认密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={confirmPass} 
                        onChange={e => setConfirmPass(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="再次输入密码"
                      />
                  </div>
                </div>
            )}

            <div className="pt-2">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading}
                    className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                >
                    {loading ? '处理中...' : (
                        mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                        (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : 
                        (mode === 'reset' ? <><Send size={16}/> 发送重置链接</> : <><KeyRound size={16}/> 修改密码</>))
                    )}
                </button>
            </div>

            <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                {mode === 'login' && (
                    <>
                        <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                        <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                    </>
                )}
                {mode === 'signup' && (
                    <div className="w-full text-center">
                        <span className="text-gray-400 font-normal">已有账号? </span>
                        <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                    </div>
                )}
                {mode === 'reset' && (
                     <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                        <ArrowLeft size={12}/> 返回登录
                     </button>
                )}
            </div>

            {mode !== 'update' && (
                <div className="mt-6 pt-4 border-t border-gray-100">
                    <h4 className="text-xs font-bold text-gray-400 mb-2 flex items-center gap-1"><HelpCircle size={12}/> 提示</h4>
                    <p className="text-[10px] text-gray-500 leading-relaxed">
                      {mode === 'reset' 
                        ? '系统将发送重置链接到您的邮箱。' 
                        : '登录后数据将自动同步。新设备登录相同账号即可同步数据。'}
                    </p>
                </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client using HARDCODED constants (SaaS Mode)
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();

    // Check if configured properly
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        // Check session
        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        const { data: { subscription } } = client.auth.onAuthStateChange((event, session) => {
          // Handle Password Recovery Event
          if (event === 'PASSWORD_RECOVERY') {
            setModal({ type: 'cloudAuth', data: { mode: 'update' } });
          }

          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => subscription.unsubscribe();
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // 2. Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       // Cloud has data, overwrite local
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    } else if (!data && !error) {
       // No cloud data, upload local
       syncToCloud(client, userId, history.present);
    }
  };

  // 3. Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    if (isSignup) {
      // Use window.location.origin to ensure a clean root URL redirect
      const { data, error } = await cloudClient.auth.signUp({ 
          email, 
          password: pass,
          options: { emailRedirectTo: window.location.origin } 
      });

      if (error) return error.message;
      // If email confirmation is enabled (default) and not clicked yet, session is null.
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  const handlePasswordReset = async (email: string) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';
    const { error } = await cloudClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin
    });
    return error?.message;
  };

  const handleUpdatePassword = async (pass: string) => {
    if (!cloudClient) return '系统未配置数据库';
    const { error } = await cloudClient.auth.updateUser({ password: pass });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates with Cloud Sync ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));

    // Sync to cloud if logged in
    if (cloudClient && cloudUser) {
        syncToCloud(cloudClient, cloudUser.id, newRooms);
    }
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          initialMode={modal.data?.mode}
          onLogin={handleCloudLogin}
          onResetPassword={handlePasswordReset}
          onUpdatePassword={handleUpdatePassword}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

