              type="number" 
              className="w-full border-b py-2 outline-none font-bold text-lg" 
              value={config.elecPrice} 
              onChange={e => setConfig({ ...config, elecPrice: e.target.value })}
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-400">水费(元/吨)</label>
            <input 
              type="number" 
              className="w-full border-b py-2 outline-none font-bold text-lg" 
              value={config.waterPrice} 
              onChange={e => setConfig({ ...config, waterPrice: e.target.value })}
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-400">默认房租</label>
            <input 
              type="number" 
              className="w-full border-b py-2 outline-none font-bold text-lg" 
              value={config.defaultRent} 
              onChange={e => setConfig({ ...config, defaultRent: e.target.value })}
            />
          </div>
        </div>

        <button onClick={onClose} className="w-full mt-8 py-3 bg-black text-white rounded-lg font-bold shadow-lg">
          保存并关闭
        </button>

        <div className="mt-6 pt-4 border-t border-gray-100">
             <button 
                onClick={() => setShowDev(!showDev)} 
                className="text-xs text-gray-300 font-bold hover:text-gray-500 w-full text-center"
             >
                {showDev ? '收起开发者选项' : '调试选项 (修复邮件空白)'}
             </button>

             {showDev && (
                 <div className="mt-4 bg-gray-50 p-3 rounded-lg border border-gray-100 space-y-4">
                     <div className="flex items-start gap-2 text-xs text-orange-600 bg-orange-50 p-2 rounded">
                        <AlertCircle size={14} className="flex-shrink-0 mt-0.5"/>
                        <p>请将代码复制到 Supabase 后台 (Authentication &gt; Email Templates)。</p>
                     </div>

                     <div>
                         <div className="flex justify-between items-center mb-1">
                            <span className="text-xs font-bold text-gray-700">1. Magic Link (验证码)</span>
                            <button 
                                onClick={() => copy(TEMPLATES.reset.body, 'otp')} 
                                className={`text-[10px] px-2 py-1 rounded font-bold flex items-center gap-1 ${copied === 'otp' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}
                            >
                                {copied === 'otp' ? <Check size={10}/> : <Copy size={10}/>} 复制HTML
                            </button>
                         </div>
                         <div className="text-[10px] text-gray-400">用于重置密码/验证码登录。标题建议: {TEMPLATES.reset.subject}</div>
                     </div>

                     <div>
                         <div className="flex justify-between items-center mb-1">
                            <span className="text-xs font-bold text-gray-700">2. Confirm Signup (注册)</span>
                            <button 
                                onClick={() => copy(TEMPLATES.confirm.body, 'confirm')} 
                                className={`text-[10px] px-2 py-1 rounded font-bold flex items-center gap-1 ${copied === 'confirm' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}
                            >
                                {copied === 'confirm' ? <Check size={10}/> : <Copy size={10}/>} 复制HTML
                            </button>
                         </div>
                         <div className="text-[10px] text-gray-400">标题建议: {TEMPLATES.confirm.subject}</div>
                     </div>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client using HARDCODED constants (SaaS Mode)
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();

    // Check if configured properly
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        // --- Robust URL Detection for Email Confirmation ---
        const checkUrlForRecovery = () => {
            const hash = window.location.hash;
            const search = window.location.search;

            // Check for Email Confirmation Link (if user still uses links)
            if ((hash && hash.includes('access_token')) || (search && search.includes('access_token'))) {
                 // Clear the ugly URL
                 window.history.replaceState(null, '', window.location.pathname);
                 setModal({ 
                    type: 'genericConfirm', 
                    title: '✅ 验证成功', 
                    content: '您的邮箱已验证成功，系统已自动登录。', 
                    onConfirm: () => setModal({ type: null }) 
                });
                return true;
            }
            return false;
        };

        // Run check immediately
        checkUrlForRecovery();
        window.addEventListener('hashchange', checkUrlForRecovery);

        // 2. Check session
        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        // 3. Listen for Auth State Changes
        const { data: { subscription } } = client.auth.onAuthStateChange((event, session) => {
          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => {
            subscription.unsubscribe();
            window.removeEventListener('hashchange', checkUrlForRecovery);
        };
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // 2. Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       // Cloud has data, overwrite local
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    } else if (!data && !error) {
       // No cloud data, upload local
       syncToCloud(client, userId, history.present);
    }
  };

  // 3. Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    const redirectUrl = window.location.origin + window.location.pathname;

    if (isSignup) {
      const { data, error } = await cloudClient.auth.signUp({ 
          email, 
          password: pass,
          options: { emailRedirectTo: redirectUrl } 
      });

      if (error) return error.message;
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  // NEW: Send OTP for Password Reset
  const handleSendOtp = async (email: string) => {
    if (!cloudClient) return '系统未配置数据库';
    // Use signInWithOtp which can trigger the Magic Link/OTP template
    const { error } = await cloudClient.auth.signInWithOtp({ email });
    return error?.message;
  };

  // NEW: Verify OTP and Update Password immediately
  const handleOtpReset = async (email: string, code: string, newPass: string) => {
      if (!cloudClient) return '系统未配置数据库';

      // 1. Verify Code (Login)
      const { data, error } = await cloudClient.auth.verifyOtp({
          email,
          token: code,
          type: 'email' // 'email' corresponds to Magic Link / OTP
      });

      if (error) return "验证码错误或已过期";
      if (!data.user) return "登录失败";

      // 2. Update Password
      const { error: updateError } = await cloudClient.auth.updateUser({ password: newPass });
      if (updateError) return updateError.message;

      return null; // Success
  };

  const handleUpdatePassword = async (pass: string) => {
    if (!cloudClient) return '系统未配置数据库';
    const { error } = await cloudClient.auth.updateUser({ password: pass });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates with Cloud Sync ---

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));

    // Sync to cloud if logged in
    if (cloudClient && cloudUser) {
        syncToCloud(cloudClient, cloudUser.id, newRooms);
    }
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          initialMode={modal.data?.mode}
          onLogin={handleCloudLogin}
          // Removed standard reset, added OTP flows
          onSendOtp={handleSendOtp}
          onOtpReset={handleOtpReset}
          onUpdatePassword={handleUpdatePassword}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail, KeyRound, CheckCircle2 } from 'lucide-react';

interface CloudAuthModalProps {
  initialMode?: 'login' | 'signup' | 'reset' | 'update';
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onSendOtp: (email: string) => Promise<string | void>;
  onOtpReset: (email: string, code: string, newPass: string) => Promise<string | void>;
  onUpdatePassword: (pass: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  initialMode = 'login', onLogin, onSendOtp, onOtpReset, onUpdatePassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset' | 'update'>(initialMode);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [otpSent, setOtpSent] = useState(false);

  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  const clearMsg = () => setMsg(null);

  const handleSubmit = async () => {
    clearMsg();

    // --- MODE 1: Normal Update (Logged In) ---
    if (mode === 'update') {
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onUpdatePassword(password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功，请重新登录' });
                setTimeout(() => { onClose(); setMode('login'); }, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // --- MODE 2: Reset via OTP (Step 1: Send Code) ---
    if (mode === 'reset' && !otpSent) {
        setLoading(true);
        try {
            const err = await onSendOtp(email);
            if (err) {
                 setMsg({ type: 'err', text: err });
            } else {
                 setOtpSent(true);
                 setMsg({ type: 'success', text: '验证码已发送，请查收邮件 (含垃圾箱)' });
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    // --- MODE 2: Reset via OTP (Step 2: Verify & Change) ---
    if (mode === 'reset' && otpSent) {
        if (!otpCode) return setMsg({ type: 'err', text: '请输入验证码' });
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onOtpReset(email, otpCode, password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功！已自动登录。' });
                setTimeout(onClose, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    // --- MODE 3: Login / Signup ---
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
        if (!isSignup) onClose();
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: any) => {
      setMode(m);
      clearMsg();
      setPassword('');
      setConfirmPass('');
      setOtpSent(false);
      setOtpCode('');
  };

  const getTitle = () => {
      if (mode === 'update') return '重置密码';
      if (currentUser) return '账号中心';
      if (mode === 'signup') return '注册账号';
      if (mode === 'reset') return otpSent ? '输入验证码' : '找回密码';
      return '登录';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Cloud className="text-blue-600"/> 
            {getTitle()}
          </h3>
          <button onClick={onClose}><X className="text-gray-400"/></button>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {currentUser && mode !== 'update' ? (
            <div className="text-center py-6">
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <Cloud size={32}/>
              </div>
              <p className="font-bold text-lg text-gray-800">已登录</p>
              <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
              <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
              <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                退出登录
              </button>
            </div>
        ) : (
          <div className="space-y-4">

            {mode !== 'update' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
                  <div className="relative">
                      <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                          type="email" 
                          value={email} 
                          onChange={e => setEmail(e.target.value)} 
                          className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                          placeholder="email@example.com"
                          disabled={mode === 'reset' && otpSent} // Lock email after sending code
                      />
                  </div>
                </div>
            )}

            {/* OTP CODE INPUT */}
            {mode === 'reset' && otpSent && (
                <div className="animate-in slide-in-from-right-4">
                  <label className="text-xs font-bold text-blue-600 mb-1 block">验证码 (已发送到邮箱)</label>
                  <div className="relative">
                      <CheckCircle2 size={16} className="absolute left-0 top-3 text-blue-500"/>
                      <input 
                          type="text" 
                          value={otpCode} 
                          onChange={e => setOtpCode(e.target.value.trim())} 
                          className="w-full border-b py-2 pl-6 text-xl font-bold outline-none border-blue-200 focus:border-blue-500 text-blue-700 tracking-widest" 
                          placeholder="123456"
                          maxLength={6}
                      />
                  </div>
                </div>
            )}

            {/* PASSWORD INPUTS (For Login, Signup, Update, OR Reset Step 2) */}
            { (mode !== 'reset' || otpSent) && (
                <div className="animate-in slide-in-from-bottom-2">
                  <label className="text-xs font-bold text-gray-400 mb-1 block">
                     {mode === 'update' || mode === 'reset' ? '新密码' : '密码'}
                  </label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="******"
                      />
                  </div>
                </div>
            )}

            {(mode === 'signup' || mode === 'update' || (mode === 'reset' && otpSent)) && (
                <div className="animate-in slide-in-from-bottom-2">
                  <label className="text-xs font-bold text-gray-400 mb-1 block">确认新密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={confirmPass} 
                        onChange={e => setConfirmPass(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="再次输入密码"
                      />
                  </div>
                </div>
            )}

            <div className="pt-2">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading}
                    className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                >
                    {loading ? '处理中...' : (
                        mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                        (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : 
                        (mode === 'reset' ? (otpSent ? <><KeyRound size={16}/> 确认修改密码</> : <><Send size={16}/> 获取验证码</>) : 
                        <><KeyRound size={16}/> 修改密码</>))
                    )}
                </button>
            </div>

            <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                {mode === 'login' && (
                    <>
                        <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                        <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                    </>
                )}
                {mode === 'signup' && (
                    <div className="w-full text-center">
                        <span className="text-gray-400 font-normal">已有账号? </span>
                        <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                    </div>
                )}
                {mode === 'reset' && (
                     <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                        <ArrowLeft size={12}/> 返回登录
                     </button>
                )}
            </div>

            {mode !== 'update' && (
                <div className="mt-6 pt-4 border-t border-gray-100">
                    <h4 className="text-xs font-bold text-gray-400 mb-2 flex items-center gap-1"><HelpCircle size={12}/> 提示</h4>
                    <p className="text-[10px] text-gray-500 leading-relaxed">
                      {mode === 'reset' 
                        ? '请确保在 Supabase 后台已配置 Magic Link 模板为显示 {{ .Token }}，否则您将收到链接而不是验证码。' 
                        : '登录后数据将自动同步。新设备登录相同账号即可同步数据。'}
                    </p>
                </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Cloud, LogIn, UserPlus, AlertCircle, HelpCircle, ArrowLeft, Send, Lock, Mail, KeyRound, CheckCircle2, Copy, Check } from 'lucide-react';

interface CloudAuthModalProps {
  initialMode?: 'login' | 'signup' | 'reset' | 'update';
  onLogin: (email: string, pass: string, isSignup: boolean) => Promise<string | void>;
  onSendOtp: (email: string) => Promise<string | void>;
  onOtpReset: (email: string, code: string, newPass: string) => Promise<string | void>;
  onUpdatePassword: (pass: string) => Promise<string | void>;
  onLogout: () => void;
  currentUser: any;
  onClose: () => void;
}

export const CloudAuthModal: React.FC<CloudAuthModalProps> = ({ 
  initialMode = 'login', onLogin, onSendOtp, onOtpReset, onUpdatePassword, onLogout, currentUser, onClose 
}) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'reset' | 'update'>(initialMode);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [otpSent, setOtpSent] = useState(false);

  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<{ type: 'err' | 'success', text: string } | null>(null);

  // Troubleshooting State
  const [showFixGuide, setShowFixGuide] = useState(false);
  const [copied, setCopied] = useState(false);

  const clearMsg = () => setMsg(null);

  const handleSubmit = async () => {
    clearMsg();

    // --- MODE 1: Normal Update (Logged In) ---
    if (mode === 'update') {
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onUpdatePassword(password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功，请重新登录' });
                setTimeout(() => { onClose(); setMode('login'); }, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    if (!email) return setMsg({ type: 'err', text: '请填写邮箱' });

    // --- MODE 2: Reset via OTP (Step 1: Send Code) ---
    if (mode === 'reset' && !otpSent) {
        setLoading(true);
        try {
            const err = await onSendOtp(email);
            if (err) {
                 setMsg({ type: 'err', text: err });
            } else {
                 setOtpSent(true);
                 setMsg({ type: 'success', text: '验证码已发送，请查收邮件 (含垃圾箱)' });
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    // --- MODE 2: Reset via OTP (Step 2: Verify & Change) ---
    if (mode === 'reset' && otpSent) {
        if (!otpCode) return setMsg({ type: 'err', text: '请输入验证码' });
        if (!password) return setMsg({ type: 'err', text: '请输入新密码' });
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });

        setLoading(true);
        try {
            const err = await onOtpReset(email, otpCode, password);
            if (err) setMsg({ type: 'err', text: err });
            else {
                setMsg({ type: 'success', text: '密码修改成功！已自动登录。' });
                setTimeout(onClose, 1500);
            }
        } catch(e: any) { setMsg({ type: 'err', text: e.message }); }
        setLoading(false);
        return;
    }

    // --- MODE 3: Login / Signup ---
    if (!password) return setMsg({ type: 'err', text: '请填写密码' });

    if (mode === 'signup') {
        if (password !== confirmPass) return setMsg({ type: 'err', text: '两次密码输入不一致' });
        if (password.length < 6) return setMsg({ type: 'err', text: '密码长度至少6位' });
    }

    setLoading(true);
    try {
      const isSignup = mode === 'signup';
      const res = await onLogin(email, password, isSignup);

      if (res === 'NEED_CONFIRMATION') {
        setMsg({ type: 'success', text: '注册成功！请前往邮箱验证。' });
      } else if (res) {
        setMsg({ type: 'err', text: typeof res === 'string' ? res : '操作失败' });
      } else {
        setMsg({ type: 'success', text: isSignup ? '注册并登录成功' : '登录成功' });
        if (!isSignup) onClose();
      }
    } catch (e: any) {
      setMsg({ type: 'err', text: e.message || 'Error' });
    }
    setLoading(false);
  };

  const switchMode = (m: any) => {
      setMode(m);
      clearMsg();
      setPassword('');
      setConfirmPass('');
      setOtpSent(false);
      setOtpCode('');
      setShowFixGuide(false);
  };

  const copyTemplate = () => {
      const tpl = `<h2>验证码</h2>\n<p>您的验证码是：</p>\n<h1 style="color:#2563EB;">{{ .Token }}</h1>\n<p>请在5分钟内使用。</p>`;
      navigator.clipboard.writeText(tpl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
  };

  const getTitle = () => {
      if (mode === 'update') return '重置密码';
      if (currentUser) return '账号中心';
      if (mode === 'signup') return '注册账号';
      if (mode === 'reset') return otpSent ? '输入验证码' : '找回密码';
      return '登录';
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-6 z-[200]">
      <div className="bg-white w-full max-w-sm rounded-xl p-6 shadow-2xl flex flex-col max-h-[90vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Cloud className="text-blue-600"/> 
            {getTitle()}
          </h3>
          <button onClick={onClose}><X className="text-gray-400"/></button>
        </div>

        {msg && (
          <div className={`mb-4 p-3 rounded-lg text-xs font-bold flex items-start gap-2 ${msg.type === 'err' ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0"/> <span className="break-all">{msg.text}</span>
          </div>
        )}

        {currentUser && mode !== 'update' ? (
            <div className="text-center py-6">
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <Cloud size={32}/>
              </div>
              <p className="font-bold text-lg text-gray-800">已登录</p>
              <p className="text-sm text-gray-500 mb-6">{currentUser.email}</p>
              <p className="text-xs text-blue-500 bg-blue-50 p-2 rounded mb-6">您的数据正在自动同步到云端</p>
              <button onClick={onLogout} className="w-full py-3 border border-gray-200 text-gray-600 rounded-lg font-bold">
                退出登录
              </button>
            </div>
        ) : (
          <div className="space-y-4">

            {mode !== 'update' && (
                <div>
                  <label className="text-xs font-bold text-gray-400 mb-1 block">邮箱</label>
                  <div className="relative">
                      <Mail size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                          type="email" 
                          value={email} 
                          onChange={e => setEmail(e.target.value)} 
                          className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                          placeholder="email@example.com"
                          disabled={mode === 'reset' && otpSent} 
                      />
                  </div>
                </div>
            )}

            {/* OTP CODE INPUT */}
            {mode === 'reset' && otpSent && (
                <div className="animate-in slide-in-from-right-4">
                  <div className="flex justify-between items-end mb-1">
                      <label className="text-xs font-bold text-blue-600 block">验证码</label>
                      <button onClick={() => setShowFixGuide(!showFixGuide)} className="text-[10px] text-red-500 underline font-bold">
                          收到的全是链接？
                      </button>
                  </div>

                  {/* FIX GUIDE BOX */}
                  {showFixGuide && (
                      <div className="bg-orange-50 border border-orange-200 p-3 rounded-lg mb-3">
                          <p className="text-[10px] text-orange-800 mb-2 font-bold">⚠️ Supabase 默认发链接不发验证码。请去后台修改：</p>
                          <ol className="text-[10px] text-orange-700 list-decimal pl-3 space-y-1 mb-2">
                              <li>登录 supabase.com Dashboard</li>
                              <li>Authentication {'>'} Email Templates</li>
                              <li>点击 <strong>Magic Link</strong> (不是Reset Password)</li>
                              <li>把内容替换为以下代码：</li>
                          </ol>
                          <button 
                            onClick={copyTemplate}
                            className="w-full bg-white border border-orange-300 rounded px-2 py-1.5 text-[10px] font-mono text-gray-600 flex items-center justify-between hover:bg-orange-100"
                          >
                            <span>{`<h2>验证码: {{ .Token }}</h2>`}</span>
                            {copied ? <Check size={12} className="text-green-600"/> : <Copy size={12}/>}
                          </button>
                          <p className="text-[10px] text-orange-600 mt-2">保存后，点击下方“重新获取”再试。</p>
                      </div>
                  )}

                  <div className="relative">
                      <CheckCircle2 size={16} className="absolute left-0 top-3 text-blue-500"/>
                      <input 
                          type="text" 
                          value={otpCode} 
                          onChange={e => setOtpCode(e.target.value.trim())} 
                          className="w-full border-b py-2 pl-6 text-xl font-bold outline-none border-blue-200 focus:border-blue-500 text-blue-700 tracking-widest" 
                          placeholder="123456"
                          maxLength={6}
                      />
                  </div>
                </div>
            )}

            {/* PASSWORD INPUTS */}
            { (mode !== 'reset' || otpSent) && (
                <div className="animate-in slide-in-from-bottom-2">
                  <label className="text-xs font-bold text-gray-400 mb-1 block">
                     {mode === 'update' || mode === 'reset' ? '新密码' : '密码'}
                  </label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="******"
                      />
                  </div>
                </div>
            )}

            {(mode === 'signup' || mode === 'update' || (mode === 'reset' && otpSent)) && (
                <div className="animate-in slide-in-from-bottom-2">
                  <label className="text-xs font-bold text-gray-400 mb-1 block">确认新密码</label>
                  <div className="relative">
                      <Lock size={16} className="absolute left-0 top-3 text-gray-400"/>
                      <input 
                        type="password" 
                        value={confirmPass} 
                        onChange={e => setConfirmPass(e.target.value)} 
                        className="w-full border-b py-2 pl-6 text-base font-bold outline-none focus:border-blue-500 transition-colors" 
                        placeholder="再次输入密码"
                      />
                  </div>
                </div>
            )}

            <div className="pt-2 flex flex-col gap-2">
                <button 
                    onClick={handleSubmit} 
                    disabled={loading}
                    className="w-full py-3 bg-black text-white rounded-lg font-bold disabled:opacity-50 flex items-center justify-center gap-2 hover:bg-gray-800 transition-colors"
                >
                    {loading ? '处理中...' : (
                        mode === 'login' ? <><LogIn size={16}/> 登录</> : 
                        (mode === 'signup' ? <><UserPlus size={16}/> 注册</> : 
                        (mode === 'reset' ? (otpSent ? <><KeyRound size={16}/> 确认修改密码</> : <><Send size={16}/> 获取验证码</>) : 
                        <><KeyRound size={16}/> 修改密码</>))
                    )}
                </button>

                {mode === 'reset' && otpSent && (
                    <button 
                        onClick={() => { setOtpSent(false); setMsg(null); }} 
                        className="text-xs text-gray-400 font-bold hover:text-black py-2"
                    >
                        没有收到？重新获取
                    </button>
                )}
            </div>

            <div className="flex justify-between items-center text-xs font-bold text-gray-500 pt-2">
                {mode === 'login' && (
                    <>
                        <button onClick={() => switchMode('reset')} className="hover:text-black">忘记密码?</button>
                        <button onClick={() => switchMode('signup')} className="text-blue-600 hover:text-blue-700">注册新账号</button>
                    </>
                )}
                {mode === 'signup' && (
                    <div className="w-full text-center">
                        <span className="text-gray-400 font-normal">已有账号? </span>
                        <button onClick={() => switchMode('login')} className="text-blue-600 hover:text-blue-700">立即登录</button>
                    </div>
                )}
                {mode === 'reset' && (
                     <button onClick={() => switchMode('login')} className="flex items-center gap-1 hover:text-black">
                        <ArrowLeft size={12}/> 返回登录
                     </button>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

