  openSettings: () => void;
  openGuide: () => void;
  navigate: (view: 'list' | 'edit' | 'add', id?: string) => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
  config: AppConfig;
  installPrompt: InstallPromptEvent | null;
  onInstall: () => void;
}

export const RoomListView: React.FC<RoomListViewProps> = ({ 
  rooms, search, filter, batch, actions, navigate, 
  setModal, openSettings, openGuide, confirmAction, config,
  installPrompt, onInstall
}) => {
  const calcTotal = (r: Room) => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || config.elecPrice;
    const wp = r.fixedWaterPrice || config.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const allBuildings = ['all', ...new Set(rooms.map(r => getBuildingName(r.roomNo)))].sort();

  let filtered = rooms;
  if (search.active) filtered = filtered.filter(r => r.roomNo.toLowerCase().includes(search.active.toLowerCase()));
  if (filter.building !== 'all') filtered = filtered.filter(r => getBuildingName(r.roomNo) === filter.building);
  if (filter.date !== 'all') filtered = filtered.filter(r => (r.payDay || 1) === parseInt(filter.date));

  const allPayDays = [...new Set(rooms.map(r => r.payDay || 1))].sort((a, b) => Number(a) - Number(b));

  // New Grouping Logic: Single group if "All" dates selected, otherwise grouped/labelled by date
  interface RoomGroup {
    label?: string;
    rooms: Room[];
  }

  const sortRooms = (list: Room[]) => list.sort((a, b) => { 
      // Primary Sort: Unpaid first (critical for rent management)
      if (a.status !== b.status) return a.status === 'unpaid' ? -1 : 1; 
      // Secondary Sort: Room Number
      return a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }); 
  });

  let displayGroups: RoomGroup[] = [];

  if (filter.date === 'all') {
      // Flattened list without date headers
      displayGroups = [{ rooms: sortRooms([...filtered]) }];
  } else {
      // Specific date view
      if (filtered.length > 0) {
        displayGroups = [{
            label: `${filter.date}号收租`,
            rooms: sortRooms([...filtered])
        }];
      }
  }

  const totalExpected = filtered.reduce((acc, r) => acc + calcTotal(r), 0);
  const totalCollected = filtered.filter(r => r.status === 'paid').reduce((acc, r) => acc + calcTotal(r), 0);

  const toggleSelect = (id: string) => { 
    const newSet = new Set(batch.ids); 
    if (newSet.has(id)) newSet.delete(id); else newSet.add(id); 
    batch.setIds(newSet); 
  };

  const handleSelectAll = () => {
      const allFilteredIds = filtered.map(r => r.id);
      const isAllSelected = allFilteredIds.every(id => batch.ids.has(id));

      if (isAllSelected) {
          // Deselect all current filtered
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.delete(id));
          batch.setIds(newSet);
      } else {
          // Select all current filtered
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.add(id));
          batch.setIds(newSet);
      }
  };

  const openBatchBill = () => {
      setModal({ type: 'batchBill', data: Array.from(batch.ids) });
  };

  return (
    <div className="pb-24">
      <div className="sticky top-0 z-30 bg-[#F5F7FA]/95 backdrop-blur-sm border-b border-gray-200 shadow-sm">
        <div className="px-4 py-3">
          {batch.isMode ? (
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 w-full bg-blue-50 p-2 rounded-lg border border-blue-200">
                    <button onClick={() => { batch.setMode(false); batch.setIds(new Set()); }} className="p-1 rounded hover:bg-blue-100">
                        <X className="text-blue-500" size={20}/>
                    </button>
                    <span className="font-bold text-blue-800 text-sm">已选 {batch.ids.size}</span>

                    <div className="ml-auto flex gap-2">
                        <button onClick={handleSelectAll} className="text-xs px-2 py-1.5 bg-white text-blue-600 rounded border border-blue-200 font-bold flex items-center gap-1">
                            <ListChecks size={14}/> 全选
                        </button>
                    </div>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={() => setModal({ type: 'batchDate' })} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-gray-700 rounded border font-bold disabled:opacity-50"
                    >
                        改日期
                    </button>
                    <button 
                        onClick={openBatchBill} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-blue-600 rounded border border-blue-200 font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Copy size={14}/> 批量账单
                    </button>
                    <button 
                        onClick={() => confirmAction("批量删除?", `确定删除选中的 ${batch.ids.size} 个房间吗？`, actions.deleteBatch)} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-red-600 rounded border border-red-100 font-bold disabled:opacity-50"
                    >
                        删除
                    </button>
                </div>
            </div>
          ) : (
            <div className="flex items-center justify-between w-full overflow-x-auto no-scrollbar gap-2">
              <div className="flex-shrink-0">
                <h1 className="text-xl font-black text-gray-800">房租管家</h1>
              </div>
              <div className="flex gap-2">
                {installPrompt && (
                   <button onClick={onInstall} className="flex-shrink-0 flex items-center gap-1 bg-black text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-md hover:scale-105 transition-transform animate-pulse">
                     <Download size={14}/> 安装
                   </button>
                )}
                <button onClick={() => setModal({ type: 'cloudAuth' })} className="flex-shrink-0 flex items-center gap-1 bg-white border border-blue-100 text-blue-600 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-blue-50 shadow-sm">
                  <Cloud size={14}/> 云同步
                </button>
                <button onClick={openGuide} className="flex-shrink-0 flex items-center gap-1 bg-blue-100 text-blue-700 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-blue-200">
                  <BookOpen size={14}/> 指南
                </button>
                <button onClick={() => setModal({ type: 'history' })} className="flex-shrink-0 flex items-center gap-1 bg-gray-100 text-gray-700 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200">
                  <History size={14}/> 历史
                </button>
                <button onClick={openSettings} className="flex-shrink-0 flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-gray-50">
                  <Settings size={14}/> 设置
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white/50 backdrop-blur-sm pb-2">
          <div className="px-4 py-2 flex gap-2 overflow-x-auto no-scrollbar">
            {allBuildings.map(b => (
              <button 
                key={b} 
                onClick={() => filter.setBuilding(b)} 
                className={`whitespace-nowrap px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${filter.building === b ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-500 border-gray-200'}`}
              >
                <Building2 size={12}/> {b === 'all' ? '所有房产' : b}
              </button>
            ))}
          </div>
          <div className="px-4 pb-2 flex gap-2 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => filter.setDate('all')} 
              className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === 'all' ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
            >
              全部日期
            </button>
            {allPayDays.map(day => (
              <button 
                key={day} 
                onClick={() => filter.setDate(day.toString())} 
                className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === day.toString() ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
              >
                {day}号收租
              </button>
            ))}
          </div>
        </div>

        <div className="px-4 py-2 flex flex-col gap-2 bg-white border-t border-gray-100">
            <div className="flex gap-2">
              <div className="flex-1 flex items-center bg-gray-100 rounded-lg px-2">
                <Search className="text-gray-400" size={16} />
                <input 
                  className="bg-transparent text-sm p-2 outline-none w-full" 
                  placeholder="输入房号..." 
                  value={search.input} 
                  onChange={e => search.setInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && search.run()}
                />
                {search.input && <button onClick={search.clear}><X size={16} className="text-gray-400"/></button>}
              </div>
              <button onClick={search.run} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-xs font-bold flex-shrink-0">搜索</button>
            </div>
            {search.active && (
              <div className="flex justify-between items-center bg-yellow-50 px-3 py-2 rounded-lg border border-yellow-100">
                <span className="text-xs text-yellow-800 font-bold">🔍 搜索 "{search.active}"，找到 {filtered.length} 个房间</span>
                <button onClick={search.clear} className="text-xs text-yellow-600 underline">清空</button>
              </div>
            )}

            {!batch.isMode && (
                <div className="flex justify-between items-center pt-2 border-t border-gray-50">
                <div className="text-xs text-gray-500 flex gap-3">
                    <span>应收 <b className="text-gray-900">¥{totalExpected.toLocaleString()}</b></span>
                    <span>已收 <b className="text-green-600">¥{totalCollected.toLocaleString()}</b></span>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => batch.setMode(true)} className="text-xs font-bold text-gray-600 bg-gray-100 px-3 py-1.5 rounded-lg flex items-center gap-1 active:bg-gray-200">
                    <CheckSquare size={12}/> 批量
                    </button>
                    <button onClick={() => setModal({ type: 'newMonth' })} className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg flex items-center gap-1 active:bg-blue-100">
                    <RotateCcw size={12}/> 结算
                    </button>
                </div>
                </div>
            )}
        </div>
      </div>

      <div className="px-4 py-4 space-y-6">
        {displayGroups.map((group, index) => (
          <div key={index}>
            {group.label && (
              <div className="flex items-center gap-2 mb-3 pl-1">
                <span className="bg-gray-200 text-gray-600 text-[10px] font-bold px-2 py-0.5 rounded">{group.label}</span>
                <div className="h-px bg-gray-200 flex-1"></div>
              </div>
            )}
            <div className="grid grid-cols-1 gap-3">
              {group.rooms.map(room => {
                const total = calcTotal(room);
                const isPaid = room.status === 'paid';
                const isSelected = batch.ids.has(room.id);
                return (
                  <div 
                    key={room.id} 
                    onClick={() => batch.isMode ? toggleSelect(room.id) : navigate('edit', room.id)} 
                    className={`relative flex items-center gap-4 p-4 rounded-xl border transition-all bg-white ${batch.isMode && isSelected ? 'border-blue-500 bg-blue-50/20' : 'border-gray-100 shadow-[0_2px_5px_rgba(0,0,0,0.02)]'} ${!batch.isMode && isPaid ? 'opacity-60 grayscale' : 'hover:border-blue-200'}`}
                  >
                    {batch.isMode && (
                      <div className={`mr-1 ${isSelected ? 'text-blue-600' : 'text-gray-300'}`}>
                        {isSelected ? <CheckSquare size={24}/> : <Square size={24}/>}
                      </div>
                    )}
                    {!batch.isMode && <div className={`absolute left-0 top-3 bottom-3 w-1 rounded-r-full ${isPaid ? 'bg-green-400' : 'bg-red-500'}`}></div>}
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center mb-1">
                        <div className="flex items-baseline gap-2 overflow-hidden">
                          <span className="text-lg font-bold text-gray-800 whitespace-nowrap">{room.roomNo}</span>
                          {room.tenantName && (
                            <span className="text-sm font-bold text-gray-500 truncate">
                              {room.tenantName}
                            </span>
                          )}
                        </div>
                        <span className="text-lg font-bold font-mono text-gray-900 flex-shrink-0 ml-2">¥{total.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center h-6">
                        <span className="text-xs text-gray-400 flex items-center gap-1">
                          <Building2 size={10}/> {getBuildingName(room.roomNo)}
                          {room.moveInDate && <span className="ml-1 text-gray-400">| 入住: {room.moveInDate}</span>}
                        </span>
                        {!batch.isMode && !isPaid && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); setModal({ type: 'bill', data: room }); }} 
                            className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded hover:bg-blue-100"
                          >
                            账单
                          </button>
                        )}
                        {isPaid && <span className="text-xs font-bold text-green-600 flex items-center gap-1"><CheckCircle size={12}/> 已收</span>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {filtered.length === 0 && (
          <div className="text-center text-gray-400 py-20 flex flex-col items-center">
            <FileText size={48} className="mx-auto text-gray-200 mb-2"/>
            <p>没有找到相关房间</p>
          </div>
        )}
      </div>

      {!batch.isMode && (
        <button 
          onClick={() => navigate('add')} 
          className="fixed bottom-8 right-6 bg-blue-600 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center z-40 hover:scale-105 transition"
        >
          <Plus size={28} />
        </button>
      )}
    </div>
  );
};

import React, { useEffect } from 'react';
import { ArrowLeft, Trash2, Zap, Droplets, LogOut, X, Calendar, User, Phone, History, CreditCard } from 'lucide-react';
import { Room, AppConfig, ActionHandlers, ModalState } from '../types';

interface RoomEditViewProps {
  room: Room | undefined;
  config: AppConfig;
  actions: ActionHandlers;
  onBack: () => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
}

export const RoomEditView: React.FC<RoomEditViewProps> = ({ 
  room, 
  config, 
  actions, 
  onBack, 
  setModal, 
  confirmAction 
}) => {
  if (!room) { 
    setTimeout(onBack, 0); 
    return null; 
  }

  const getVal = (v: any) => parseFloat(v) || 0;
  const elecPrice = room.fixedElecPrice || config.elecPrice;
  const waterPrice = room.fixedWaterPrice || config.waterPrice;
  const elecUsage = getVal(room.elecCurr) - getVal(room.elecPrev);
  const elecTotal = Math.max(0, elecUsage * getVal(elecPrice));
  const waterUsage = getVal(room.waterCurr) - getVal(room.waterPrev);
  const waterTotal = Math.max(0, waterUsage * getVal(waterPrice));
  const extraFees = room.extraFees || [];
  const extraTotal = extraFees.reduce((sum, item) => sum + getVal(item.amount), 0);
  const grandTotal = getVal(room.rent) + elecTotal + waterTotal + extraTotal;

  const handleChange = (f: keyof Room, v: any) => actions.updateRoom(room.id, { [f]: v });

  // Special handler for Move-In Date change to sync PayDay
  const handleDateChange = (dateStr: string) => {
    const updates: Partial<Room> = { moveInDate: dateStr };
    if (dateStr) {
      const day = new Date(dateStr).getDate();
      if (!isNaN(day)) updates.payDay = day;
    }
    actions.updateRoom(room.id, updates);
  };

  const handleExtraChange = (newFees: any[]) => actions.updateRoom(room.id, { extraFees: newFees });

  const toggleStatus = () => { 
    actions.saveRoom(room.id, { status: room.status === 'paid' ? 'unpaid' : 'paid' }); 
    onBack(); 
  };

  const addExtra = () => handleExtraChange([...extraFees, { id: Date.now(), name: '', amount: '' }]);

  const updateExtra = (idx: number, f: string, v: string) => { 
    const n = [...extraFees]; 
    // @ts-ignore
    n[idx][f] = v; 
    handleExtraChange(n); 
  };

  const requestRemoveExtra = (idx: number) => {
    confirmAction(
      "删除费用?",
      `确定删除 "${extraFees[idx].name || '未命名费用'}" 吗？`,
      () => handleExtraChange(extraFees.filter((_, i) => i !== idx))
    );
  };

  const handleMoveOutRequest = () => {
    setModal({ type: 'moveOut', data: room });
  };

  const handleSingleSettle = () => {
      confirmAction(
          "确认结算本月?", 
          "系统将保存当前账单到历史记录，把本月读数转为上月读数，并自动设置下一个账单周期的日期。", 
          () => actions.settleSingleRoom(room.id)
      );
  };

  // Validation Logic
  const isPhoneValid = !room.tenantPhone || /^\d{11}$/.test(room.tenantPhone);
  const isIdCardValid = !room.tenantIdCard || /^.{18}$/.test(room.tenantIdCard); // Strictly check for 18 characters

  return (
    <div className="flex flex-col min-h-screen bg-white">
      <div className="px-4 py-3 flex items-center justify-between border-b border-gray-100 sticky top-0 bg-white z-20">
        <button onClick={onBack} className="flex items-center gap-1 text-gray-600 hover:text-gray-900 font-bold text-sm">
          <ArrowLeft size={18}/> 返回
        </button>
        <span className="font-bold text-lg text-gray-800">{room.roomNo}</span>
        <button 
          onClick={() => confirmAction("删除房间?", "确定删除此房间吗？数据可恢复。", () => actions.deleteSingle(room.id))} 
          className="flex items-center gap-1 text-red-500 hover:bg-red-50 px-2 py-1 rounded-lg transition-colors"
        >
          <Trash2 size={16} />
          <span className="text-xs font-bold">删除</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-6 pb-32 space-y-8 mt-6">
        <div className="text-center bg-blue-50 py-6 rounded-2xl border border-blue-100 relative group">
          <p className="text-xs text-blue-400 font-bold uppercase mb-1">本月应收</p>
          <div className="text-5xl font-black text-blue-900 font-mono tracking-tighter">¥{grandTotal.toLocaleString()}</div>
          <div className="absolute top-2 right-3 text-blue-300 text-xs font-bold bg-white/50 px-2 py-1 rounded-lg">押金: {room.deposit || 0}</div>

          {/* History Button */}
          <button 
            onClick={() => setModal({ type: 'billHistory', data: room })}
            className="absolute top-2 left-3 text-blue-400 hover:text-blue-600 p-1 bg-white/50 rounded-lg flex items-center gap-1 text-xs font-bold"
          >
            <History size={14}/> 历史
          </button>
        </div>

        {/* Tenant Info */}
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
          <div className="flex items-center gap-2 mb-3">
             <User size={14} className="text-gray-500"/>
             <span className="text-xs font-bold text-gray-500">租客信息</span>
          </div>
          <div className="flex gap-4 mb-3">
             <div className="flex-1">
                 <div className="relative">
                    <User size={14} className="absolute left-2 top-2.5 text-gray-400" />
                    <input 
                      placeholder="租客姓名" 
                      className="w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border border-gray-200 rounded outline-none"
                      value={room.tenantName || ''}
                      onChange={e => handleChange('tenantName', e.target.value)}
                    />
                 </div>
             </div>
             <div className="flex-1">
                 <div className="relative">
                    <Phone size={14} className="absolute left-2 top-2.5 text-gray-400" />
                    <input 
                      type="tel"
                      placeholder="联系电话" 
                      className={`w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border rounded outline-none ${!isPhoneValid ? 'border-red-500 text-red-600 bg-red-50' : 'border-gray-200'}`}
                      value={room.tenantPhone || ''}
                      onChange={e => handleChange('tenantPhone', e.target.value)}
                    />
                 </div>
                 {!isPhoneValid && <p className="text-[10px] text-red-500 mt-1 pl-1">电话需11位</p>}
             </div>
          </div>

          <div className="w-full">
             <div className="relative">
                <CreditCard size={14} className="absolute left-2 top-2.5 text-gray-400" />
                <input 
                  placeholder="身份证号" 
                  className={`w-full pl-7 pr-2 py-2 text-sm font-bold bg-white border rounded outline-none ${!isIdCardValid ? 'border-red-500 text-red-600 bg-red-50' : 'border-gray-200'}`}
                  value={room.tenantIdCard || ''}
                  onChange={e => handleChange('tenantIdCard', e.target.value)}
                  maxLength={18}
                />
             </div>
             {!isIdCardValid && <p className="text-[10px] text-red-500 mt-1 pl-1">身份证需18位</p>}
          </div>
        </div>

        {/* Room Details Grid - 2x2 Layout */}
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">房租(元)</label>
            <input type="number" value={room.rent || ''} onChange={(e) => handleChange('rent', e.target.value)} className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none" placeholder="0" />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">押金(元)</label>
            <input type="number" value={room.deposit || ''} onChange={(e) => handleChange('deposit', e.target.value)} className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none text-blue-600" placeholder="0" />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">入住日期</label>
            <input 
              type="date" 
              value={room.moveInDate || ''} 
              onChange={(e) => handleDateChange(e.target.value)} 
              className="w-full text-sm font-bold border-b border-gray-200 py-1.5 outline-none" 
            />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">收租时间(号)</label>
            <input 
              type="number" 
              value={room.payDay || ''} 
              onChange={(e) => handleChange('payDay', parseInt(e.target.value))} 
              className="w-full text-lg font-bold border-b border-gray-200 py-1 outline-none" 
              placeholder="1" 
            />
          </div>
        </div>

        {/* Billing Cycle Section */}
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
           <div className="flex items-center justify-between mb-2">
             <div className="flex items-center gap-2">
               <Calendar size={14} className="text-gray-500"/>
               <span className="text-xs font-bold text-gray-500">账单日期 (选填)</span>
             </div>
             <button
               onClick={handleSingleSettle}
               className="text-[10px] bg-blue-600 text-white px-2 py-1 rounded font-bold shadow-sm hover:bg-blue-700"
             >
               📅 结算/开启下月
             </button>
           </div>
           <div className="flex items-center gap-2">
             <input 
               type="date" 
               className="flex-1 bg-white border border-gray-200 rounded px-2 py-2 text-sm font-bold text-gray-800 outline-none"
               value={room.billStartDate || ''}
               onChange={e => handleChange('billStartDate', e.target.value)}
             />
             <span className="text-gray-400 text-xs">至</span>
             <input 
               type="date" 
               className="flex-1 bg-white border border-gray-200 rounded px-2 py-2 text-sm font-bold text-gray-800 outline-none"
               value={room.billEndDate || ''}
               onChange={e => handleChange('billEndDate', e.target.value)}
             />
           </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white border border-gray-100 p-4 rounded-xl shadow-sm">
            <div className="flex justify-between mb-3">
              <div className="text-sm font-bold text-gray-800 flex items-center gap-2">
                <Zap size={16} className="text-yellow-500"/> 电费 <span className="text-xs text-gray-400">({elecPrice}/度)</span>
              </div>
              <span className="font-bold text-yellow-600">¥{elecTotal.toFixed(1)}</span>
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 block mb-1">上月读数</label>
                <input type="number" value={room.elecPrev || ''} onChange={(e) => handleChange('elecPrev', e.target.value)} className="w-full bg-gray-50 rounded p-2 text-sm font-bold text-gray-500 outline-none" placeholder=""/>
              </div>
              <div className="flex-1">
                <label className="text-[10px] text-blue-600 font-bold block mb-1">本月读数</label>
                <input type="number" autoFocus value={room.elecCurr || ''} onChange={(e) => handleChange('elecCurr', e.target.value)} className="w-full bg-blue-50 border border-blue-200 rounded p-2 text-lg font-bold text-gray-900 outline-none" placeholder=""/>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-4 rounded-xl shadow-sm">
            <div className="flex justify-between mb-3">
              <div className="text-sm font-bold text-gray-800 flex items-center gap-2">
                <Droplets size={16} className="text-blue-500"/> 水费 <span className="text-xs text-gray-400">({waterPrice}/吨)</span>
              </div>
              <span className="font-bold text-blue-600">¥{waterTotal.toFixed(1)}</span>
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 block mb-1">上月读数</label>
                <input type="number" value={room.waterPrev || ''} onChange={(e) => handleChange('waterPrev', e.target.value)} className="w-full bg-gray-50 rounded p-2 text-sm font-bold text-gray-500 outline-none" placeholder=""/>
              </div>
              <div className="flex-1">
                <label className="text-[10px] text-blue-600 font-bold block mb-1">本月读数</label>
                <input type="number" value={room.waterCurr || ''} onChange={(e) => handleChange('waterCurr', e.target.value)} className="w-full bg-blue-50 border border-blue-200 rounded p-2 text-lg font-bold text-gray-900 outline-none" placeholder=""/>
              </div>
            </div>
          </div>
        </div>

        <div>
          <div className="flex justify-between items-center mb-2">
            <label className="text-xs font-bold text-gray-400 uppercase">额外费用</label>
            <button onClick={addExtra} className="text-blue-600 text-xs font-bold bg-blue-50 px-2 py-1 rounded">+ 添加</button>
          </div>
          <div className="space-y-3">
            {extraFees.map((fee, idx) => (
              <div key={idx} className="flex items-center gap-3">
                <input placeholder="项目" value={fee.name} onChange={(e) => updateExtra(idx, 'name', e.target.value)} className="flex-1 border-b border-gray-100 py-2 text-sm font-bold outline-none"/>
                <input type="number" placeholder="0" value={fee.amount} onChange={(e) => updateExtra(idx, 'amount', e.target.value)} className="w-20 border-b border-gray-100 py-2 text-sm font-bold text-right outline-none"/>
                <button onClick={() => requestRemoveExtra(idx)} className="text-gray-300 hover:text-red-500">
                  <X size={16}/>
                </button>
              </div>
            ))}
          </div>
        </div>

        <div className="pt-4 border-t border-gray-100">
          <button onClick={handleMoveOutRequest} className="w-full py-3 border border-red-200 text-red-600 rounded-xl font-bold text-sm flex items-center justify-center gap-2">
            <LogOut size={16}/> 办理退租
          </button>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-5 bg-white border-t border-gray-100 z-40">
        <div className="grid grid-cols-[1fr_2fr] gap-4 max-w-md mx-auto">
          <button onClick={() => setModal({ type: 'bill', data: room })} className="bg-gray-100 text-gray-600 rounded-lg py-3 font-bold text-sm">生成账单</button>
          <button onClick={toggleStatus} className={`rounded-lg py-3 font-bold text-white shadow-sm flex items-center justify-center gap-2 ${room.status === 'paid' ? 'bg-gray-400' : 'bg-black'}`}>
            {room.status === 'paid' ? '标记未收' : '确认收款'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { safeGetStorage, calculateBillPeriod } from './utils';
import { STORAGE_KEY_CONFIG, STORAGE_KEY_DATA, DEFAULT_CONFIG } from './constants';
import { Room, AppConfig, HistoryState, ActionHandlers, ModalState, InstallPromptEvent, BillRecord } from './types';

// Components
import { RoomListView } from './components/RoomListView';
import { RoomEditView } from './components/RoomEditView';
import { UserGuideView } from './components/UserGuideView';
import { AddRoomModal } from './components/AddRoomModal';
import { SettingsModal } from './components/SettingsModal';
import { HistoryModal } from './components/HistoryModal';
import { BillPreviewModal } from './components/BillPreviewModal';
import { BillHistoryModal } from './components/BillHistoryModal';
import { NewMonthModal } from './components/NewMonthModal';
import { BatchDateModal } from './components/BatchDateModal';
import { GenericConfirmModal } from './components/GenericConfirmModal';
import { MoveOutModal } from './components/MoveOutModal';
import { BatchBillModal } from './components/BatchBillModal';
import { CloudAuthModal } from './components/CloudAuthModal';

export default function App() {
  // --- Core State ---
  const [history, setHistory] = useState<HistoryState>({ archives: [], present: [] });
  const [isLoaded, setIsLoaded] = useState(false);
  const [view, setView] = useState<'list' | 'edit' | 'add' | 'settings' | 'guide'>('list');
  const [activeRoomId, setActiveRoomId] = useState<string | null>(null);

  // Search & Filter
  const [searchInput, setSearchInput] = useState('');
  const [activeSearch, setActiveSearch] = useState('');
  const [activeBuilding, setActiveBuilding] = useState('all');
  const [activeDateTab, setActiveDateTab] = useState('all');

  // Batch Selection
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal State
  const [modal, setModal] = useState<ModalState>({ type: null });

  // Config State (Local preferences only, connection details are constants)
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  // Cloud Sync State
  const [cloudClient, setCloudClient] = useState<SupabaseClient | null>(null);
  const [cloudUser, setCloudUser] = useState<any>(null);
  const [isCloudConfigured, setIsCloudConfigured] = useState(false);

  // PWA Install Prompt State
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);

  // --- Initialization ---
  useEffect(() => {
    try {
      const savedConfig = safeGetStorage(STORAGE_KEY_CONFIG, null);
      if (savedConfig) setConfig(savedConfig);

      let initialRooms = safeGetStorage<Room[]>(STORAGE_KEY_DATA, []);
      if (!initialRooms || initialRooms.length === 0) {
        initialRooms = safeGetStorage('landlord_data_v21_fresh', []); 
      }
      if (!Array.isArray(initialRooms)) initialRooms = [];

      setHistory({
        archives: [{ data: initialRooms, desc: '初始状态', time: new Date().toISOString() }],
        present: initialRooms
      });

      if (initialRooms.length === 0) setView('guide');
      setIsLoaded(true);
    } catch (e) {
      setIsLoaded(true);
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setInstallPrompt(e as InstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // --- Auto Save to LocalStorage ---
  useEffect(() => {
    if (isLoaded && history.present) {
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(history.present));
    }
  }, [history.present, isLoaded]);

  useEffect(() => {
    if (isLoaded) localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [config, isLoaded]);

  // --- Cloud Sync Logic ---

  // Initialize Client
  useEffect(() => {
    const url = DEFAULT_CONFIG.supabaseUrl?.trim();
    const key = DEFAULT_CONFIG.supabaseKey?.trim();
    const isValid = !!(url && key && url.startsWith('http') && key.length > 20);
    setIsCloudConfigured(isValid);

    if (isValid) {
      try {
        const client = createClient(url!, key!);
        setCloudClient(client);

        const checkUrlForRecovery = () => {
            const hash = window.location.hash;
            const search = window.location.search;
            if ((hash && hash.includes('access_token')) || (search && search.includes('access_token'))) {
                 window.history.replaceState(null, '', window.location.pathname);
                 setModal({ 
                    type: 'genericConfirm', 
                    title: '✅ 验证成功', 
                    content: '您的邮箱已验证成功，系统已自动登录。', 
                    onConfirm: () => setModal({ type: null }) 
                });
                return true;
            }
            return false;
        };

        checkUrlForRecovery();
        window.addEventListener('hashchange', checkUrlForRecovery);

        client.auth.getSession().then(({ data: { session } }) => {
          setCloudUser(session?.user || null);
          if (session?.user) {
             syncFromCloud(client, session.user.id);
          }
        });

        const { data: { subscription } } = client.auth.onAuthStateChange((event, session) => {
          const user = session?.user || null;
          setCloudUser(user);
          if (user) syncFromCloud(client, user.id);
        });

        return () => {
            subscription.unsubscribe();
            window.removeEventListener('hashchange', checkUrlForRecovery);
        };
      } catch (e) {
        console.error("Supabase init failed", e);
      }
    }
  }, []);

  // Download Data
  const syncFromCloud = async (client: SupabaseClient, userId: string) => {
    const { data, error } = await client
      .from('landlord_backup')
      .select('data')
      .eq('user_id', userId)
      .single();

    if (data && data.data) {
       setHistory(prev => ({
           ...prev,
           present: data.data,
           archives: [{ data: data.data, desc: '云端同步', time: new Date().toISOString() }, ...prev.archives].slice(0, 50)
       }));
    }
    // Note: We don't implicitly upload here anymore; the Auto Sync Effect will handle uploading local data if cloud is empty/different.
  };

  // Upload Data
  const syncToCloud = async (client: SupabaseClient, userId: string, rooms: Room[]) => {
      await client.from('landlord_backup').upsert({
          user_id: userId,
          data: rooms,
          updated_at: new Date().toISOString()
      });
  };

  // --- AUTOMATIC CLOUD BACKUP EFFECT ---
  // This watches for ANY change in data and uploads it to cloud after a short delay.
  useEffect(() => {
    if (!isLoaded || !cloudClient || !cloudUser) return;

    // Debounce to prevent spamming API while typing
    const timer = setTimeout(() => {
        syncToCloud(cloudClient, cloudUser.id, history.present).catch(err => {
            console.warn("Auto backup failed (network error?):", err);
        });
    }, 2000);

    return () => clearTimeout(timer);
  }, [history.present, isLoaded, cloudClient, cloudUser]);


  // --- Handlers ---

  const handleCloudLogin = async (email: string, pass: string, isSignup: boolean) => {
    if (!cloudClient) return '系统未配置数据库，请联系管理员。';

    const redirectUrl = window.location.origin + window.location.pathname;

    if (isSignup) {
      const { data, error } = await cloudClient.auth.signUp({ 
          email, 
          password: pass,
          options: { emailRedirectTo: redirectUrl } 
      });

      if (error) return error.message;
      if (data.user && !data.session) {
        return 'NEED_CONFIRMATION';
      }
      return;
    } else {
      const { error } = await cloudClient.auth.signInWithPassword({ email, password: pass });
      return error?.message;
    }
  };

  const handleUpdatePassword = async (pass: string) => {
    if (!cloudClient) return '系统未配置数据库';
    const { error } = await cloudClient.auth.updateUser({ password: pass });
    return error?.message;
  };

  const handleCloudLogout = async () => {
      if (cloudClient) await cloudClient.auth.signOut();
  };

  // --- Calculation Helpers ---
  const calculateTotal = (r: Room, cfg: AppConfig): number => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || cfg.elecPrice;
    const wp = r.fixedWaterPrice || cfg.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const processSettlement = (r: Room): Room => {
      const record: BillRecord = {
          id: Date.now().toString() + Math.random(),
          recordedAt: new Date().toISOString(),
          startDate: r.billStartDate || '',
          endDate: r.billEndDate || '',
          rent: r.rent,
          elecPrev: r.elecPrev,
          elecCurr: r.elecCurr,
          waterPrev: r.waterPrev,
          waterCurr: r.waterCurr,
          extraFees: [...(r.extraFees || [])],
          total: calculateTotal(r, config),
          tenantName: r.tenantName,
          tenantIdCard: r.tenantIdCard,
          roomNo: r.roomNo
      };
      const newHistory = [...(r.billHistory || []), record];
      const payDayInt = r.payDay ? parseInt(String(r.payDay)) : 1;
      const { start, end } = calculateBillPeriod(payDayInt, r.billEndDate);

      return {
        ...r,
        elecPrev: r.elecCurr ? parseFloat(r.elecCurr) : r.elecPrev,
        elecCurr: '',
        waterPrev: r.waterCurr ? parseFloat(r.waterCurr) : r.waterPrev,
        waterCurr: '',
        status: 'unpaid' as const,
        billStartDate: start,
        billEndDate: end,
        billHistory: newHistory
      };
  };

  // --- Core State Updates ---
  // Note: We removed explicit syncToCloud calls here because the useEffect above handles it automatically.

  const commitChange = (newRooms: Room[], desc: string) => {
    setHistory(curr => ({
      archives: [{ data: newRooms, desc, time: new Date().toISOString() }, ...curr.archives].slice(0, 50),
      present: newRooms
    }));
  };

  const handleRestore = (index: number) => {
    const target = history.archives[index];
    if (target) {
      commitChange(target.data, `恢复至: ${target.desc}`);
      setModal({ type: null });
    }
  };

  const handleInstallApp = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const createRoomObj = (data: Partial<Room>, index = 0): Room => {
    const payDay = typeof data.payDay === 'number' ? data.payDay : 1;
    const { start, end } = calculateBillPeriod(payDay);

    return {
      id: `${Date.now()}-${index}-${Math.random().toString(36).slice(2, 6)}`,
      roomNo: data.roomNo || '未命名',
      rent: data.rent || config.defaultRent,
      deposit: data.deposit || '',
      payDay: payDay,
      moveInDate: data.moveInDate,
      tenantName: '',
      tenantPhone: '',
      tenantIdCard: '',
      fixedElecPrice: data.fixedElecPrice || '',
      fixedWaterPrice: data.fixedWaterPrice || '',
      elecPrev: 0,
      elecCurr: '',
      waterPrev: 0,
      waterCurr: '',
      extraFees: [],
      status: 'unpaid',
      lastUpdated: new Date().toISOString(),
      billStartDate: start,
      billEndDate: end,
      billHistory: []
    };
  };

  const actions: ActionHandlers = {
    addRoom: (data) => {
      if (history.present.some(r => r.roomNo === data.roomNo)) return alert("房间号已存在");
      commitChange([...history.present, createRoomObj(data)], `添加 ${data.roomNo}`);
      setView('list');
    },

    batchAddConfirmed: (previewRooms) => {
      const uniqueRooms = previewRooms.filter(n => !history.present.some(o => o.roomNo === n.roomNo));
      if (uniqueRooms.length === 0) return alert("没有生成新房间(可能全部已存在)");
      const newItems = uniqueRooms.map((d, i) => createRoomObj(d, i));
      commitChange([...history.present, ...newItems], `批量生成 ${newItems.length} 间`);
      setView('list');
    },

    updateRoom: (id, data) => {
      setHistory(curr => ({
        ...curr,
        present: curr.present.map(r => r.id === id ? { ...r, ...data } : r)
      }));
    },

    saveRoom: (id, data) => {
      commitChange(
        history.present.map(r => r.id === id ? { ...r, ...data } : r),
        "更新房间信息"
      );
    },

    deleteSingle: (id) => {
      commitChange(history.present.filter(r => r.id !== id), "删除房间");
      setView('list');
      setModal({ type: null });
    },

    deleteBatch: () => {
      commitChange(
        history.present.filter(r => !selectedIds.has(r.id)),
        `批量删除 ${selectedIds.size} 项`
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
    },

    updateBatchDate: (day) => {
      commitChange(
        history.present.map(r => selectedIds.has(r.id) ? { ...r, payDay: parseInt(day) } : r),
        "批量修改日期"
      );
      setSelectedIds(new Set());
      setIsSelectionMode(false);
      setModal({ type: null });
      setActiveDateTab('all');
    },

    newMonth: (targetDay) => {
      const updated = history.present.map(r => {
        if (targetDay !== 'all') {
            const rDay = r.payDay ? parseInt(String(r.payDay)) : 1;
            const tDay = parseInt(String(targetDay));
            if (rDay !== tDay) return r;
        }
        return processSettlement(r);
      });
      commitChange(updated, "批量开启新月份");
      setModal({ type: null });
    },

    settleSingleRoom: (id: string) => {
        const target = history.present.find(r => r.id === id);
        if (!target) return;
        const updated = history.present.map(r => r.id !== id ? r : processSettlement(r));
        commitChange(updated, `单个结算: ${target.roomNo}`);
    },

    moveOut: (id, returnDeposit) => {
      const target = history.present.find(r => r.id === id);
      if (!target) return;
      const updated: Room = { 
        ...target, 
        deposit: returnDeposit ? '0' : target.deposit, 
        tenantName: '',
        tenantPhone: '',
        tenantIdCard: '',
        status: 'unpaid', 
        extraFees: [] 
      };
      commitChange(
        history.present.map(r => r.id === id ? updated : r), 
        `房间 ${target.roomNo} 退租`
      );
      setModal({ type: null });
      setView('list');
    }
  };

  const handleSearch = () => setActiveSearch(searchInput);
  const clearSearch = () => { setSearchInput(''); setActiveSearch(''); };

  const confirmAction = (title: string, content: string, action: () => void) => {
    setModal({ type: 'genericConfirm', title, content, onConfirm: action });
  };

  const viewHistoryRecord = (record: BillRecord) => {
     const currentRoom = history.present.find(r => r.roomNo === record.roomNo);
     if (!currentRoom) return;

     const tempRoom: Room = {
         ...currentRoom, 
         id: record.id,
         roomNo: record.roomNo,
         rent: record.rent,
         elecPrev: record.elecPrev,
         elecCurr: record.elecCurr,
         waterPrev: record.waterPrev,
         waterCurr: record.waterCurr,
         extraFees: record.extraFees,
         billStartDate: record.startDate,
         billEndDate: record.endDate,
         tenantName: record.tenantName,
         tenantIdCard: record.tenantIdCard,
         deposit: '0', 
         payDay: 1, 
         status: 'paid',
         lastUpdated: record.recordedAt
     };
     setModal({ type: 'bill', data: tempRoom });
  };

  if (!isLoaded) return <div className="flex h-screen items-center justify-center text-gray-500">正在启动...</div>;

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-[#1A1A1A]">
      {view === 'list' && (
        <RoomListView
          rooms={history.present}
          search={{ input: searchInput, setInput: setSearchInput, active: activeSearch, run: handleSearch, clear: clearSearch }}
          filter={{ building: activeBuilding, setBuilding: setActiveBuilding, date: activeDateTab, setDate: setActiveDateTab }}
          batch={{ isMode: isSelectionMode, setMode: setIsSelectionMode, ids: selectedIds, setIds: setSelectedIds }}
          actions={actions}
          openSettings={() => setView('settings')}
          openGuide={() => setView('guide')}
          navigate={(v, id) => { setView(v); if (id) setActiveRoomId(id); }}
          setModal={setModal}
          confirmAction={confirmAction}
          config={config}
          installPrompt={installPrompt}
          onInstall={handleInstallApp}
        />
      )}

      {view === 'edit' && activeRoomId && (
        <RoomEditView
          room={history.present.find(r => r.id === activeRoomId)}
          config={config}
          actions={actions}
          onBack={() => setView('list')}
          setModal={setModal}
          confirmAction={confirmAction}
        />
      )}

      {view === 'guide' && <UserGuideView onClose={() => setView('list')} />}

      {view === 'add' && (
        <AddRoomModal 
          config={config} 
          onSave={actions.addRoom} 
          onBatchConfirmed={actions.batchAddConfirmed} 
          onCancel={() => setView('list')} 
          confirmAction={confirmAction} 
        />
      )}

      {view === 'settings' && (
        <SettingsModal config={config} setConfig={setConfig} onClose={() => setView('list')} />
      )}

      {/* Modals */}
      {modal.type === 'history' && (
        <HistoryModal archives={history.archives} onRestore={handleRestore} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'bill' && modal.data && (
        <BillPreviewModal room={modal.data} config={config} onClose={() => setModal({ type: null })} />
      )}

      {modal.type === 'billHistory' && modal.data && (
        <BillHistoryModal 
            room={modal.data} 
            onSelect={viewHistoryRecord}
            onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'batchBill' && modal.data && (
        <BatchBillModal 
          rooms={history.present.filter(r => modal.data.includes(r.id)).sort((a,b) => a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }))} 
          config={config} 
          onClose={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'moveOut' && modal.data && (
        <MoveOutModal 
          room={modal.data} 
          config={config} 
          onConfirm={actions.moveOut} 
          onCancel={() => setModal({ type: null })} 
        />
      )}

      {modal.type === 'newMonth' && (
        <NewMonthModal rooms={history.present} onAction={actions.newMonth} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'batchDate' && (
        <BatchDateModal count={selectedIds.size} onConfirm={actions.updateBatchDate} onCancel={() => setModal({ type: null })} />
      )}

      {modal.type === 'genericConfirm' && modal.onConfirm && (
        <GenericConfirmModal
          title={modal.title}
          content={modal.content}
          onConfirm={() => { modal.onConfirm!(); setModal({ type: null }); }}
          onCancel={() => setModal({ type: null })}
        />
      )}

      {modal.type === 'cloudAuth' && (
        <CloudAuthModal 
          initialMode={modal.data?.mode}
          onLogin={handleCloudLogin}
          onUpdatePassword={handleUpdatePassword}
          onLogout={handleCloudLogout}
          currentUser={cloudUser}
          onClose={() => setModal({ type: null })}
        />
      )}
    </div>
  );
}

import React from 'react';
import { 
  X, CheckSquare, Search, BookOpen, History, Settings, 
  Building2, RotateCcw, FileText, Square, CheckCircle, Plus,
  ListChecks, Copy, Download, Cloud
} from 'lucide-react';
import { Room, AppConfig, ActionHandlers, ModalState, InstallPromptEvent } from '../types';
import { getBuildingName } from '../utils';

interface RoomListViewProps {
  rooms: Room[];
  search: {
    input: string;
    setInput: (v: string) => void;
    active: string;
    run: () => void;
    clear: () => void;
  };
  filter: {
    building: string;
    setBuilding: (v: string) => void;
    date: string;
    setDate: (v: string) => void;
  };
  batch: {
    isMode: boolean;
    setMode: (v: boolean) => void;
    ids: Set<string>;
    setIds: (v: Set<string>) => void;
  };
  actions: ActionHandlers;
  openSettings: () => void;
  openGuide: () => void;
  navigate: (view: 'list' | 'edit' | 'add', id?: string) => void;
  setModal: React.Dispatch<React.SetStateAction<ModalState>>;
  confirmAction: (title: string, content: string, action: () => void) => void;
  config: AppConfig;
  installPrompt: InstallPromptEvent | null;
  onInstall: () => void;
}

export const RoomListView: React.FC<RoomListViewProps> = ({ 
  rooms, search, filter, batch, actions, navigate, 
  setModal, openSettings, openGuide, confirmAction, config,
  installPrompt, onInstall
}) => {
  const calcTotal = (r: Room) => {
    const getVal = (v: any) => parseFloat(v) || 0;
    const ep = r.fixedElecPrice || config.elecPrice;
    const wp = r.fixedWaterPrice || config.waterPrice;
    const e = (getVal(r.elecCurr) - getVal(r.elecPrev)) * getVal(ep);
    const w = (getVal(r.waterCurr) - getVal(r.waterPrev)) * getVal(wp);
    const extra = (r.extraFees || []).reduce((sum, item) => sum + getVal(item.amount), 0);
    return Math.max(0, getVal(r.rent) + Math.max(0, e) + Math.max(0, w) + extra);
  };

  const allBuildings = ['all', ...new Set(rooms.map(r => getBuildingName(r.roomNo)))].sort();

  let filtered = rooms;
  if (search.active) filtered = filtered.filter(r => r.roomNo.toLowerCase().includes(search.active.toLowerCase()));
  if (filter.building !== 'all') filtered = filtered.filter(r => getBuildingName(r.roomNo) === filter.building);
  if (filter.date !== 'all') filtered = filtered.filter(r => (r.payDay || 1) === parseInt(filter.date));

  const allPayDays = [...new Set(rooms.map(r => r.payDay || 1))].sort((a, b) => Number(a) - Number(b));

  // New Grouping Logic: Single group if "All" dates selected, otherwise grouped/labelled by date
  interface RoomGroup {
    label?: string;
    rooms: Room[];
  }

  const sortRooms = (list: Room[]) => list.sort((a, b) => { 
      // Primary Sort: Unpaid first (critical for rent management)
      if (a.status !== b.status) return a.status === 'unpaid' ? -1 : 1; 
      // Secondary Sort: Room Number
      return a.roomNo.localeCompare(b.roomNo, undefined, { numeric: true }); 
  });

  let displayGroups: RoomGroup[] = [];

  if (filter.date === 'all') {
      // Flattened list without date headers
      displayGroups = [{ rooms: sortRooms([...filtered]) }];
  } else {
      // Specific date view
      if (filtered.length > 0) {
        displayGroups = [{
            label: `${filter.date}号收租`,
            rooms: sortRooms([...filtered])
        }];
      }
  }

  const totalExpected = filtered.reduce((acc, r) => acc + calcTotal(r), 0);
  const totalCollected = filtered.filter(r => r.status === 'paid').reduce((acc, r) => acc + calcTotal(r), 0);

  const toggleSelect = (id: string) => { 
    const newSet = new Set(batch.ids); 
    if (newSet.has(id)) newSet.delete(id); else newSet.add(id); 
    batch.setIds(newSet); 
  };

  const handleSelectAll = () => {
      const allFilteredIds = filtered.map(r => r.id);
      const isAllSelected = allFilteredIds.every(id => batch.ids.has(id));

      if (isAllSelected) {
          // Deselect all current filtered
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.delete(id));
          batch.setIds(newSet);
      } else {
          // Select all current filtered
          const newSet = new Set(batch.ids);
          allFilteredIds.forEach(id => newSet.add(id));
          batch.setIds(newSet);
      }
  };

  const openBatchBill = () => {
      setModal({ type: 'batchBill', data: Array.from(batch.ids) });
  };

  return (
    <div className="pb-24">
      <div className="sticky top-0 z-30 bg-[#F5F7FA]/95 backdrop-blur-sm border-b border-gray-200 shadow-sm">
        <div className="px-4 py-3">
          {batch.isMode ? (
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2 w-full bg-blue-50 p-2 rounded-lg border border-blue-200">
                    <button onClick={() => { batch.setMode(false); batch.setIds(new Set()); }} className="p-1 rounded hover:bg-blue-100">
                        <X className="text-blue-500" size={20}/>
                    </button>
                    <span className="font-bold text-blue-800 text-sm">已选 {batch.ids.size}</span>

                    <div className="ml-auto flex gap-2">
                        <button onClick={handleSelectAll} className="text-xs px-2 py-1.5 bg-white text-blue-600 rounded border border-blue-200 font-bold flex items-center gap-1">
                            <ListChecks size={14}/> 全选
                        </button>
                    </div>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={() => setModal({ type: 'batchDate' })} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-gray-700 rounded border font-bold disabled:opacity-50"
                    >
                        改日期
                    </button>
                    <button 
                        onClick={openBatchBill} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-blue-600 rounded border border-blue-200 font-bold disabled:opacity-50 flex items-center justify-center gap-1"
                    >
                        <Copy size={14}/> 批量账单
                    </button>
                    <button 
                        onClick={() => confirmAction("批量删除?", `确定删除选中的 ${batch.ids.size} 个房间吗？`, actions.deleteBatch)} 
                        disabled={batch.ids.size === 0} 
                        className="flex-1 text-xs py-2 bg-white text-red-600 rounded border border-red-100 font-bold disabled:opacity-50"
                    >
                        删除
                    </button>
                </div>
            </div>
          ) : (
            <div className="flex items-center justify-between w-full">
              {/* Title: Hidden on small screens (<640px) to give space for buttons, shown as Short version */}
              <div className="flex-shrink-0 hidden sm:block">
                <h1 className="text-xl font-black text-gray-800">房租管家</h1>
              </div>
              <div className="flex-shrink-0 sm:hidden pr-2">
                <h1 className="text-xl font-black text-gray-800">房租</h1>
              </div>

              {/* Toolbar Buttons: Flex-1 to take space, justify-end to align right */}
              <div className="flex flex-1 justify-end items-center gap-2 overflow-x-auto no-scrollbar mask-linear-fade">
                {installPrompt && (
                   <button onClick={onInstall} className="flex-shrink-0 flex items-center gap-1 bg-black text-white px-3 py-1.5 rounded-full text-xs font-bold shadow-md hover:scale-105 transition-transform whitespace-nowrap">
                     <Download size={14}/> 安装
                   </button>
                )}
                <button onClick={() => setModal({ type: 'cloudAuth' })} className="flex-shrink-0 flex items-center gap-1 bg-white border border-blue-100 text-blue-600 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-blue-50 shadow-sm whitespace-nowrap">
                  <Cloud size={14}/> 云同步
                </button>
                <button onClick={openGuide} className="flex-shrink-0 flex items-center gap-1 bg-blue-100 text-blue-700 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-blue-200 whitespace-nowrap">
                  <BookOpen size={14}/> 指南
                </button>
                <button onClick={() => setModal({ type: 'history' })} className="flex-shrink-0 flex items-center gap-1 bg-gray-100 text-gray-700 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 whitespace-nowrap">
                  <History size={14}/> 历史
                </button>
                <button onClick={openSettings} className="flex-shrink-0 flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-3 py-1.5 rounded-full text-xs font-bold hover:bg-gray-50 whitespace-nowrap">
                  <Settings size={14}/> 设置
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white/50 backdrop-blur-sm pb-2">
          <div className="px-4 py-2 flex gap-2 overflow-x-auto no-scrollbar">
            {allBuildings.map(b => (
              <button 
                key={b} 
                onClick={() => filter.setBuilding(b)} 
                className={`whitespace-nowrap px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${filter.building === b ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-500 border-gray-200'}`}
              >
                <Building2 size={12}/> {b === 'all' ? '所有房产' : b}
              </button>
            ))}
          </div>
          <div className="px-4 pb-2 flex gap-2 overflow-x-auto no-scrollbar">
            <button 
              onClick={() => filter.setDate('all')} 
              className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === 'all' ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
            >
              全部日期
            </button>
            {allPayDays.map(day => (
              <button 
                key={day} 
                onClick={() => filter.setDate(day.toString())} 
                className={`whitespace-nowrap px-3 py-1 rounded-full text-[10px] font-bold border ${filter.date === day.toString() ? 'bg-gray-700 text-white border-gray-700' : 'bg-transparent text-gray-400 border-transparent'}`}
              >
                {day}号收租
              </button>
            ))}
          </div>
        </div>

        <div className="px-4 py-2 flex flex-col gap-2 bg-white border-t border-gray-100">
            <div className="flex gap-2">
              <div className="flex-1 flex items-center bg-gray-100 rounded-lg px-2">
                <Search className="text-gray-400" size={16} />
                <input 
                  className="bg-transparent text-sm p-2 outline-none w-full" 
                  placeholder="输入房号..." 
                  value={search.input} 
                  onChange={e => search.setInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && search.run()}
                />
                {search.input && <button onClick={search.clear}><X size={16} className="text-gray-400"/></button>}
              </div>
              <button onClick={search.run} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-xs font-bold flex-shrink-0">搜索</button>
            </div>
            {search.active && (
              <div className="flex justify-between items-center bg-yellow-50 px-3 py-2 rounded-lg border border-yellow-100">
                <span className="text-xs text-yellow-800 font-bold">🔍 搜索 "{search.active}"，找到 {filtered.length} 个房间</span>
                <button onClick={search.clear} className="text-xs text-yellow-600 underline">清空</button>
              </div>
            )}

            {!batch.isMode && (
                <div className="flex justify-between items-center pt-2 border-t border-gray-50">
                <div className="text-xs text-gray-500 flex gap-3">
                    <span>应收 <b className="text-gray-900">¥{totalExpected.toLocaleString()}</b></span>
                    <span>已收 <b className="text-green-600">¥{totalCollected.toLocaleString()}</b></span>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => batch.setMode(true)} className="text-xs font-bold text-gray-600 bg-gray-100 px-3 py-1.5 rounded-lg flex items-center gap-1 active:bg-gray-200">
                    <CheckSquare size={12}/> 批量
                    </button>
                    <button onClick={() => setModal({ type: 'newMonth' })} className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg flex items-center gap-1 active:bg-blue-100">
                    <RotateCcw size={12}/> 结算
                    </button>
                </div>
                </div>
            )}
        </div>
      </div>

      <div className="px-4 py-4 space-y-6">
        {displayGroups.map((group, index) => (
          <div key={index}>
            {group.label && (
              <div className="flex items-center gap-2 mb-3 pl-1">
                <span className="bg-gray-200 text-gray-600 text-[10px] font-bold px-2 py-0.5 rounded">{group.label}</span>
                <div className="h-px bg-gray-200 flex-1"></div>
              </div>
            )}
            <div className="grid grid-cols-1 gap-3">
              {group.rooms.map(room => {
                const total = calcTotal(room);
                const isPaid = room.status === 'paid';
                const isSelected = batch.ids.has(room.id);
                return (
                  <div 
                    key={room.id} 
                    onClick={() => batch.isMode ? toggleSelect(room.id) : navigate('edit', room.id)} 
                    className={`relative flex items-center gap-4 p-4 rounded-xl border transition-all bg-white ${batch.isMode && isSelected ? 'border-blue-500 bg-blue-50/20' : 'border-gray-100 shadow-[0_2px_5px_rgba(0,0,0,0.02)]'} ${!batch.isMode && isPaid ? 'opacity-60 grayscale' : 'hover:border-blue-200'}`}
                  >
                    {batch.isMode && (
                      <div className={`mr-1 ${isSelected ? 'text-blue-600' : 'text-gray-300'}`}>
                        {isSelected ? <CheckSquare size={24}/> : <Square size={24}/>}
                      </div>
                    )}
                    {!batch.isMode && <div className={`absolute left-0 top-3 bottom-3 w-1 rounded-r-full ${isPaid ? 'bg-green-400' : 'bg-red-500'}`}></div>}
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center mb-1">
                        <div className="flex items-baseline gap-2 overflow-hidden">
                          <span className="text-lg font-bold text-gray-800 whitespace-nowrap">{room.roomNo}</span>
                          {room.tenantName && (
                            <span className="text-sm font-bold text-gray-500 truncate">
                              {room.tenantName}
                            </span>
                          )}
                        </div>
                        <span className="text-lg font-bold font-mono text-gray-900 flex-shrink-0 ml-2">¥{total.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center h-6">
                        <span className="text-xs text-gray-400 flex items-center gap-1">
                          <Building2 size={10}/> {getBuildingName(room.roomNo)}
                          {room.moveInDate && <span className="ml-1 text-gray-400">| 入住: {room.moveInDate}</span>}
                        </span>
                        {!batch.isMode && !isPaid && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); setModal({ type: 'bill', data: room }); }} 
                            className="text-xs font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded hover:bg-blue-100"
                          >
                            账单
                          </button>
                        )}
                        {isPaid && <span className="text-xs font-bold text-green-600 flex items-center gap-1"><CheckCircle size={12}/> 已收</span>}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {filtered.length === 0 && (
          <div className="text-center text-gray-400 py-20 flex flex-col items-center">
            <FileText size={48} className="mx-auto text-gray-200 mb-2"/>
            <p>没有找到相关房间</p>
          </div>
        )}
      </div>

      {!batch.isMode && (
        <button 
          onClick={() => navigate('add')} 
          className="fixed bottom-8 right-6 bg-blue-600 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center z-40 hover:scale-105 transition"
        >
          <Plus size={28} />
        </button>
      )}
    </div>
  );
};
